//! ObjSpace — Python object operation dispatch.
#![allow(non_camel_case_types, non_snake_case)]
//!
//! pypy/interpreter/baseobjspace.py — the core ObjSpace interface.
//!
//! Binary/unary operation dispatch (add, sub, compare, etc.) lives in
//! `crate::objspace::descroperation`; printf-style formatting lives in
//! `crate::objspace::std::formatting`. Both are re-exported here so
//! existing `crate::baseobjspace::add` paths continue to resolve.

// Suppress unsafe-in-unsafe-fn warnings; our unsafe fns are inherently
// working with raw pointers throughout and wrapping every call in an
// additional unsafe block adds noise without safety benefit.
#![allow(unsafe_op_in_unsafe_fn)]

use majit_rlib::rbigint::{RBigInt as BigInt, RBigIntGcRoot};

use std::cell::{Cell, RefCell};
use std::collections::HashMap;

use crate::function::is_function;
pub use crate::{PyError, PyErrorKind, PyResult};
use pyre_object::unicodeobject::is_str;
use pyre_object::*;
use rustpython_wtf8::{Wtf8, Wtf8Buf};

// ── Re-exports from split-out modules ────────────────────────────────
pub use crate::objspace::descroperation::*;

// ── Pending dict-key-callback error slot ─────────────────────────────
// The `r_dict(eq_w, hash_w)` callbacks (`pyre_object_hash_w_trampoline`
// / `pyre_object_eq_w_trampoline` in pyre-jit) cannot return a `Result`
// across the pyre-object dict probe, so on a raising `__hash__` or
// `__eq__` they stash the concrete PyError here.  Dict entry gates call
// `take_pending_hash_error` after a checked dict op returns
// `DictKeyError` to recover whichever exception was raised.
thread_local! {
    static PENDING_HASH_ERROR: Cell<Option<PyError>> = const { Cell::new(None) };
    static PENDING_ERROR_FROM_HASH: Cell<bool> = const { Cell::new(false) };
}

/// Store an error raised by the equality half of the dict `r_dict` callback
/// pair.  The historical name is retained for existing callers; hash
/// callbacks use [`set_pending_dict_hash_error`] so Python 3.14's hash-only
/// dict-key error remapping does not rewrite equality errors.
pub fn set_pending_hash_error(e: PyError) {
    PENDING_HASH_ERROR.with(|cell| cell.set(Some(e)));
    PENDING_ERROR_FROM_HASH.with(|cell| cell.set(false));
}

pub fn set_pending_dict_hash_error(e: PyError) {
    PENDING_HASH_ERROR.with(|cell| cell.set(Some(e)));
    PENDING_ERROR_FROM_HASH.with(|cell| cell.set(true));
}

/// `dont_look_inside`: the `PENDING_HASH_ERROR` thread-local `.with`
/// read has no extractable graph; the call stays a residual.
#[majit_macros::dont_look_inside]
pub fn take_pending_hash_error() -> PyError {
    PENDING_ERROR_FROM_HASH.with(|cell| cell.set(false));
    PENDING_HASH_ERROR.with(|cell| {
        cell.take()
            .unwrap_or_else(|| PyError::type_error("unhashable type"))
    })
}

/// Convert the two failure modes of a checked set-table operation back into
/// the Python exception carried by PyPy's `r_dict` operation.
pub fn map_set_update_error(err: pyre_object::setobject::SetUpdateError) -> PyError {
    match err {
        pyre_object::setobject::SetUpdateError::Key(_) => take_pending_hash_error(),
        pyre_object::setobject::SetUpdateError::ChangedSize => {
            PyError::runtime_error("Set changed size during iteration")
        }
    }
}

/// Root the exception parked in `PENDING_HASH_ERROR` while a raising
/// `__hash__`/`__eq__` propagates across a dict probe. Its `PyError` holds GC
/// refs the precise collector does not reach through the raw `Cell`; forward
/// them in place via [`PyError::walk_gc_refs`]. Never materialises the
/// lazy-null `exc_object`.
pub fn walk_pending_hash_error(visitor: &mut dyn FnMut(&mut majit_ir::GcRef)) {
    PENDING_HASH_ERROR.with(|cell| {
        unsafe { walk_pending_hash_error_area(cell as *const _ as *const (), visitor) };
    });
}

pub(crate) fn capture_pending_hash_error_area() -> *const () {
    PENDING_HASH_ERROR.with(|cell| cell as *const _ as *const ())
}

/// Walk the deferred dict callback error belonging to one stopped mutator.
///
/// # Safety
/// `data` must come from [`capture_pending_hash_error_area`], and the owning
/// mutator must be quiesced.
pub(crate) unsafe fn walk_pending_hash_error_area(
    data: *const (),
    visitor: &mut dyn FnMut(&mut majit_ir::GcRef),
) {
    let cell = unsafe { &*(data as *const Cell<Option<PyError>>) };
    // SAFETY: the owning mutator is stopped, so the collector has exclusive
    // access to the Cell interior while forwarding the PyError's object slots.
    let opt = unsafe { &mut *cell.as_ptr() };
    if let Some(err) = opt.as_mut() {
        err.walk_gc_refs(visitor);
    }
}

/// interp_gc.py — clear `space.fromcache(MethodCache)` before an
/// explicit full collection.
#[majit_macros::dont_look_inside]
pub fn clear_method_cache() {
    // SAFETY: the GIL is held, and nothing here runs Python code.
    let cache = unsafe { method_cache_mut() };
    for entry in cache.entries.iter_mut() {
        *entry = MethodCacheEntry::EMPTY;
    }
}

/// CPython 3.14 `dict_unhashable_type` (`Objects/dictobject.c`) parity.
/// Only an exact `TypeError` raised while hashing is replaced; equality
/// callback errors, non-TypeError exceptions, and TypeError subclasses pass
/// through unchanged.
#[majit_macros::dont_look_inside]
pub fn take_pending_dict_key_error(key: PyObjectRef) -> PyError {
    take_pending_hash_error_for(key, wrap_dict_key_hash_error)
}

/// The set-element counterpart, for a caller that reached the shared hash
/// table through a set.  The two containers name the operand differently in
/// the message they raise, so a set caller taking the dict recovery reports a
/// dict key for an element that never was one.
#[majit_macros::dont_look_inside]
pub fn take_pending_set_element_error(item: PyObjectRef) -> PyError {
    take_pending_hash_error_for(item, wrap_set_element_hash_error)
}

/// Recover the exception a failed hash left pending and give it the calling
/// container's context.  [`take_pending_hash_error`] is the same recovery
/// without the context, for a caller with no operand to name.  An error from
/// anywhere but the hash is returned as raised: only hashing is what the
/// wrappers describe.
fn take_pending_hash_error_for(
    subject: PyObjectRef,
    wrap: fn(PyObjectRef, PyError) -> PyError,
) -> PyError {
    let from_hash = PENDING_ERROR_FROM_HASH.with(|cell| cell.replace(false));
    let err = PENDING_HASH_ERROR.with(|cell| {
        cell.take()
            .unwrap_or_else(|| PyError::type_error("unhashable type"))
    });
    if !from_hash {
        return err;
    }
    wrap(subject, err)
}

/// The direct-hash counterpart of [`take_pending_dict_key_error`], used by
/// bytecode paths which compute the key hash before entering `r_dict`.
///
/// Python 3.14 adds dict-key context to an exact `TypeError` raised while
/// hashing. A different exception, including a `TypeError` subclass,
/// propagates unchanged.
pub fn wrap_dict_key_hash_error(key: PyObjectRef, err: PyError) -> PyError {
    if err.kind != PyErrorKind::TypeError {
        return err;
    }
    if !err.exc_object.is_null() {
        let exact_type_error = cached_type_error();
        let raised_type = crate::typedef::r#type(err.exc_object).map_or(PY_NULL, |p| p.as_ptr());
        if exact_type_error.is_none_or(|expected| !std::ptr::eq(raised_type, expected)) {
            return err;
        }
    }
    // The wrapped message becomes this exception's own `args[0]`, so it is
    // carried as the value it is; escaping belongs to whatever displays it.
    PyError::type_error(crate::display::wtf8_format!(
        format!(
            "cannot use '{}' as a dict key (",
            object_functionstr_type_name(key)
        ),
        err.message_wtf8(),
        ")",
    ))
}

/// Python 3.14's set-element counterpart of [`wrap_dict_key_hash_error`].
pub fn wrap_set_element_hash_error(item: PyObjectRef, err: PyError) -> PyError {
    if err.kind != PyErrorKind::TypeError {
        return err;
    }
    if !err.exc_object.is_null() {
        let exact_type_error = cached_type_error();
        let raised_type = crate::typedef::r#type(err.exc_object).map_or(PY_NULL, |p| p.as_ptr());
        if exact_type_error.is_none_or(|expected| !std::ptr::eq(raised_type, expected)) {
            return err;
        }
    }
    PyError::type_error(crate::display::wtf8_format!(
        format!(
            "cannot use '{}' as a set element (",
            object_functionstr_type_name(item)
        ),
        err.message_wtf8(),
        ")",
    ))
}

/// Compatibility alias for PyPy's base-object type.
/// PyPy frequently models interpreter values as subclasses of `W_Root`.
pub type W_Root = PyObjectRef;

/// Compatibility marker for a type mismatch in descriptor lookup.
#[derive(Debug, Clone)]
pub struct DescrMismatch;

/// Compatibility marker for lock-sensitive APIs that are disabled under
/// this no-GIL runtime.
#[derive(Debug, Clone)]
pub struct CannotHaveLock;

/// `baseobjspace.py SpaceCache`: a Cache plus its owning object space.
///
/// Keys/results remain typed so a TypeDef key need not masquerade as a Python
/// object pointer. Object-valued results must clone identity, not the object.
/// The space is retained by its actual handle/reference type; this base does
/// not manufacture a Python object pointer for a native ObjSpace.
#[derive(Debug)]
pub struct SpaceCache<K = PyObjectRef, V = PyObjectRef, S = PyObjectRef> {
    pub space: S,
    base: majit_rlib::cache::Cache<K, V>,
}

impl<K, V, S: Default> Default for SpaceCache<K, V, S> {
    fn default() -> Self {
        Self::new(S::default())
    }
}

/// The concrete subclass methods called by SpaceCache._build/_ready.
/// The owner embeds a SpaceCache and reads that base's `space` when building.
pub trait SpaceCacheBuild<K, V> {
    type Error;

    fn build(&self, key: &K) -> Result<V, majit_rlib::cache::CacheError<Self::Error>>;

    fn ready(&self, _result: &V) -> Result<(), majit_rlib::cache::CacheError<Self::Error>> {
        Ok(())
    }
}

// Rust's explicit subclass receiver for SpaceCache._build -> self.build and
// SpaceCache._ready -> self.ready. No borrow of cache storage spans callbacks.
struct SpaceCacheHooks<'a, B>(&'a B);

impl<K, V, B: SpaceCacheBuild<K, V>> majit_rlib::cache::CacheBuilder<K, V>
    for SpaceCacheHooks<'_, B>
{
    type Error = B::Error;

    fn _build(&self, key: &K) -> Result<V, majit_rlib::cache::CacheError<Self::Error>> {
        self.0.build(key)
    }

    fn _ready(&self, result: &V) -> Result<(), majit_rlib::cache::CacheError<Self::Error>> {
        self.0.ready(result)
    }
}

impl<K, V, S> SpaceCache<K, V, S> {
    pub const fn new(space: S) -> Self {
        Self {
            space,
            base: majit_rlib::cache::Cache::EMPTY,
        }
    }

    pub fn visit_values_mut(&self, visit: impl FnMut(&mut V)) {
        self.base.visit_values_mut(visit);
    }
}

impl<K: Clone + Eq + std::hash::Hash, V: Clone, S> SpaceCache<K, V, S> {
    pub fn getorbuild<B: SpaceCacheBuild<K, V>>(
        &self,
        key: K,
        owner: &B,
    ) -> Result<V, majit_rlib::cache::CacheError<B::Error>> {
        self.base.getorbuild(key, &SpaceCacheHooks(owner))
    }

    pub fn _freeze_(&self) -> bool {
        self.base._freeze_()
    }
}

/// An initialization-time callable with stable identity as a cache key.
/// `baseobjspace.py InternalSpaceCache._build` calls this object with space.
/// A function address alone is not a substitute for Python callable identity.
pub trait SpaceCallable<S>: Clone + Eq + std::hash::Hash {
    type Value: Clone;
    type Error;

    fn call(&self, space: &S) -> Result<Self::Value, majit_rlib::cache::CacheError<Self::Error>>;
}

/// `baseobjspace.py InternalSpaceCache`: Cache directly, not a SpaceCache.
/// Each object space owns its cache; no TLS or process-wide result table.
pub struct InternalSpaceCache<F: SpaceCallable<S>, S> {
    pub space: S,
    base: majit_rlib::cache::Cache<F, F::Value>,
}

impl<F: SpaceCallable<S>, S> InternalSpaceCache<F, S> {
    pub fn new(space: S) -> Self {
        Self {
            space,
            base: majit_rlib::cache::Cache::default(),
        }
    }

    pub fn getorbuild(
        &self,
        callable: F,
    ) -> Result<F::Value, majit_rlib::cache::CacheError<F::Error>> {
        self.base.getorbuild(callable, self)
    }

    pub fn _freeze_(&self) -> bool {
        self.base._freeze_()
    }

    pub fn visit_values_mut(&self, visit: impl FnMut(&mut F::Value)) {
        self.base.visit_values_mut(visit);
    }
}

impl<F: SpaceCallable<S>, S> majit_rlib::cache::CacheBuilder<F, F::Value>
    for InternalSpaceCache<F, S>
{
    type Error = F::Error;

    fn _build(&self, callable: &F) -> Result<F::Value, majit_rlib::cache::CacheError<Self::Error>> {
        callable.call(&self.space)
    }
}

#[cfg(test)]
mod space_cache_tests {
    use super::{InternalSpaceCache, SpaceCache, SpaceCacheBuild, SpaceCallable};
    use majit_rlib::cache::CacheError;
    use std::sync::Arc;
    use std::sync::atomic::{AtomicUsize, Ordering};

    struct Owner {
        base: SpaceCache<usize, Arc<(usize, usize)>, usize>,
        builds: AtomicUsize,
        readies: AtomicUsize,
    }

    impl Owner {
        fn new(space: usize) -> Self {
            Self {
                base: SpaceCache::new(space),
                builds: AtomicUsize::new(0),
                readies: AtomicUsize::new(0),
            }
        }
    }

    impl SpaceCacheBuild<usize, Arc<(usize, usize)>> for Owner {
        type Error = ();

        fn build(&self, key: &usize) -> Result<Arc<(usize, usize)>, CacheError<()>> {
            self.builds.fetch_add(1, Ordering::Relaxed);
            Ok(Arc::new((self.base.space, *key)))
        }

        fn ready(&self, result: &Arc<(usize, usize)>) -> Result<(), CacheError<()>> {
            self.readies.fetch_add(1, Ordering::Relaxed);
            assert!(Arc::ptr_eq(result, &self.base.getorbuild(result.1, self)?));
            Ok(())
        }
    }

    #[test]
    fn space_cache_delegates_and_keeps_per_space_identity() {
        let a = Owner::new(11);
        let b = Owner::new(22);
        let first = a.base.getorbuild(1, &a).unwrap();
        assert_eq!(*first, (11, 1));
        assert!(Arc::ptr_eq(&first, &a.base.getorbuild(1, &a).unwrap()));
        let other = b.base.getorbuild(1, &b).unwrap();
        assert_eq!(*other, (22, 1));
        assert!(!Arc::ptr_eq(&first, &other));
        assert_eq!(a.builds.load(Ordering::Relaxed), 1);
        assert_eq!(a.readies.load(Ordering::Relaxed), 1);
        assert!(a.base._freeze_());
        assert_eq!(*a.base.getorbuild(2, &a).unwrap(), (11, 2));
    }

    #[test]
    fn space_cache_concurrent_callers_share_result() {
        let owner = Owner::new(11);
        std::thread::scope(|scope| {
            let threads: Vec<_> = (0..4)
                .map(|_| scope.spawn(|| owner.base.getorbuild(1, &owner).unwrap()))
                .collect();
            let results: Vec<_> = threads.into_iter().map(|t| t.join().unwrap()).collect();
            assert!(results.iter().all(|v| Arc::ptr_eq(v, &results[0])));
        });
        assert_eq!(owner.builds.load(Ordering::Relaxed), 1);
        assert_eq!(owner.readies.load(Ordering::Relaxed), 1);
    }

    #[derive(Clone, PartialEq, Eq, Hash)]
    struct Callable(usize);

    impl SpaceCallable<usize> for Callable {
        type Value = Arc<(usize, usize)>;
        type Error = ();

        fn call(&self, space: &usize) -> Result<Self::Value, CacheError<()>> {
            Ok(Arc::new((*space, self.0)))
        }
    }

    #[test]
    fn internal_space_cache_keys_the_callable_and_passes_its_space() {
        let a = InternalSpaceCache::<Callable, _>::new(11);
        let b = InternalSpaceCache::<Callable, _>::new(22);
        let first = a.getorbuild(Callable(1)).unwrap();
        assert_eq!(*first, (11, 1));
        assert!(Arc::ptr_eq(&first, &a.getorbuild(Callable(1)).unwrap()));
        assert_eq!(*a.getorbuild(Callable(2)).unwrap(), (11, 2));
        let other = b.getorbuild(Callable(1)).unwrap();
        assert_eq!(*other, (22, 1));
        assert!(!Arc::ptr_eq(&first, &other));
        assert!(a._freeze_());
    }
}

/// Compatibility helper used by `ObjSpace` bootstrap in PyPy.
#[derive(Debug, Default)]
pub struct AppExecCache {
    base: SpaceCache,
}

impl AppExecCache {
    pub fn new(space: PyObjectRef) -> Self {
        Self {
            base: SpaceCache::new(space),
        }
    }

    pub fn build(&self, _source: PyObjectRef) -> PyObjectRef {
        let _ = self.base.space;
        std::ptr::null_mut()
    }
}

/// Native class-object identities admitted by ObjSpace.fromcache. These keys
/// represent constructor objects, not function addresses or result type IDs.
/// Extend alongside each real SpaceCache subclass, not a parallel registry.
///
/// `GatewayCache` and `TypeCache` live as `ObjSpace` fields
/// (`gateway_cache()`, `gettypeobject`), not as fromcache keys.
/// `PREBUILT` is `const`, so those fields cannot be `Arc`-shared with a
/// second fromcache instance. Production does not call `fromcache` for them.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub enum SpaceCacheClass {
    ClassDictStrategy,
    SysState,
}

/// A `fromcache` value plus the IsolatedStrong that keeps an isolated
/// space alive. InternalSpaceCache stores Isolated(Weak); `fromcache`
/// upgrades only this wrapper so `ObjSpace → cache → ObjSpace` cannot cycle.
pub struct RetainedSpaceCache<T> {
    #[allow(dead_code)]
    keep_alive: SpaceHandle,
    inner: std::sync::Arc<T>,
}

impl<T> Clone for RetainedSpaceCache<T> {
    fn clone(&self) -> Self {
        Self {
            keep_alive: self.keep_alive.clone(),
            inner: self.inner.clone(),
        }
    }
}

impl<T> RetainedSpaceCache<T> {
    fn stored(space: SpaceHandle, inner: std::sync::Arc<T>) -> Self {
        Self {
            keep_alive: space,
            inner,
        }
    }

    fn retain_owner(self) -> Self {
        Self {
            keep_alive: self.keep_alive.retain(),
            inner: self.inner,
        }
    }

    pub fn ptr_eq(this: &Self, other: &Self) -> bool {
        std::sync::Arc::ptr_eq(&this.inner, &other.inner)
    }
}

impl<T> std::ops::Deref for RetainedSpaceCache<T> {
    type Target = T;

    fn deref(&self) -> &T {
        &self.inner
    }
}

#[derive(Clone)]
pub enum SpaceCacheInstance {
    ClassDictStrategy(RetainedSpaceCache<crate::objspace::std::classdict::ClassDictStrategy>),
    SysState(RetainedSpaceCache<crate::module::sys::state::SysState>),
}

impl SpaceCacheInstance {
    /// Attach IsolatedStrong to a cloned cache so an escaped result keeps
    /// its isolated space alive. The stored clone is left untouched.
    fn retain_owner(self) -> Self {
        match self {
            Self::ClassDictStrategy(cache) => Self::ClassDictStrategy(cache.retain_owner()),
            Self::SysState(cache) => Self::SysState(cache.retain_owner()),
        }
    }
}

/// Process-wide prebuilt space, or an isolated test space.
/// Upstream the translated `ObjSpace` is one prebuilt instance; tests
/// still construct extra spaces the way `StdObjSpace()` can be new'd
/// at host time.
#[derive(Clone)]
pub enum SpaceHandle {
    ProcessWide,
    Isolated(std::sync::Weak<ObjSpace>),
    /// Strong handle held by a `fromcache` result so the returned
    /// cache keeps its isolated space alive (`InternalSpaceCache`
    /// owns space strongly upstream).
    IsolatedStrong(std::sync::Arc<ObjSpace>),
}

/// Keeps an isolated `Arc` alive for the duration of a `&ObjSpace` borrow.
pub enum SpaceGuard<'a> {
    Static(&'a ObjSpace),
    Held(std::sync::Arc<ObjSpace>),
}

impl std::ops::Deref for SpaceGuard<'_> {
    type Target = ObjSpace;

    fn deref(&self) -> &ObjSpace {
        match self {
            Self::Static(space) => space,
            Self::Held(space) => space,
        }
    }
}

impl SpaceHandle {
    pub fn get(&self) -> SpaceGuard<'_> {
        match self {
            Self::ProcessWide => SpaceGuard::Static(object_space()),
            Self::Isolated(space) => {
                SpaceGuard::Held(space.upgrade().expect("live InternalSpaceCache owner"))
            }
            Self::IsolatedStrong(space) => SpaceGuard::Held(space.clone()),
        }
    }

    /// Upgrade a construction-time Weak into the strong handle a
    /// published cache holds, so dropping the caller's Arc does not
    /// collect the space while the cache is live.
    fn retain(&self) -> Self {
        match self {
            Self::ProcessWide => Self::ProcessWide,
            Self::Isolated(space) => {
                Self::IsolatedStrong(space.upgrade().expect("live InternalSpaceCache owner"))
            }
            Self::IsolatedStrong(space) => Self::IsolatedStrong(space.clone()),
        }
    }
}

impl SpaceCallable<SpaceHandle> for SpaceCacheClass {
    type Value = SpaceCacheInstance;
    type Error = std::convert::Infallible;

    fn call(
        &self,
        space: &SpaceHandle,
    ) -> Result<Self::Value, majit_rlib::cache::CacheError<Self::Error>> {
        // Store Isolated(Weak). IsolatedStrong is attached only to the
        // clone `fromcache` returns (`SpaceCacheInstance::retain_owner`).
        Ok(match self {
            Self::ClassDictStrategy => {
                SpaceCacheInstance::ClassDictStrategy(RetainedSpaceCache::stored(
                    space.clone(),
                    std::sync::Arc::new(crate::objspace::std::classdict::ClassDictStrategy::new(
                        space.clone(),
                    )),
                ))
            }
            Self::SysState => SpaceCacheInstance::SysState(RetainedSpaceCache::stored(
                space.clone(),
                std::sync::Arc::new(crate::module::sys::state::SysState::new()),
            )),
        })
    }
}

/// One `space.w_*` attribute of an object space: written while the space
/// initializes, then rewritten only by the collector through
/// [`ObjSpace::walk_cache_roots`].
pub struct SpaceAttr(std::cell::UnsafeCell<PyObjectRef>);

// Written once during space initialization, then only by the collector.
unsafe impl Sync for SpaceAttr {}
unsafe impl Send for SpaceAttr {}

impl SpaceAttr {
    pub const fn new() -> Self {
        Self(std::cell::UnsafeCell::new(std::ptr::null_mut()))
    }

    /// The attribute, or null before the space set it.
    #[inline]
    pub fn get(&self) -> PyObjectRef {
        unsafe { *self.0.get() }
    }

    /// `setattr(space, 'w_' + name, w_obj)`. The space is prebuilt, so the
    /// store is a prebuilt-family store (`remember_young_pointer`).
    fn set(&self, w_obj: PyObjectRef) {
        unsafe { *self.0.get() = w_obj };
        pyre_object::gc_roots::mark_prebuilt_roots_dirty();
    }

    fn walk(&self, forward: &mut dyn FnMut(&mut PyObjectRef)) {
        let slot = unsafe { &mut *self.0.get() };
        if !slot.is_null() {
            forward(slot);
        }
    }
}

/// baseobjspace.py ObjSpace.__init__: own InternalSpaceCache, whose callable
/// keys construct per-space caches. The process-wide instance is a prebuilt
/// static (`OBJECT_SPACE`); isolated test spaces keep an `Arc`.
pub struct ObjSpace {
    fromcache: InternalSpaceCache<SpaceCacheClass, SpaceHandle>,
    sys_state: crate::module::sys::state::SysState,
    class_dict_strategy: crate::objspace::std::classdict::ClassDictStrategy,
    gateway_cache: crate::gateway::GatewayCache,
    type_cache: crate::objspace::std::typeobject::TypeCache,
    /// `space.w_object` and `space.w_type`: `StdObjSpace.initialize` does
    /// `setattr(self, 'w_' + typedef.name, w_type)` for each builtin type.
    w_object: SpaceAttr,
    w_type: SpaceAttr,
    /// `space.w_BaseException` and `space.w_TypeError`:
    /// `ObjSpace.export_builtin_exceptions` does
    /// `setattr(self, "w_" + excname, w_exc)`.
    w_base_exception: SpaceAttr,
    w_type_error: SpaceAttr,
}

impl ObjSpace {
    pub const PREBUILT: Self = Self {
        fromcache: InternalSpaceCache {
            space: SpaceHandle::ProcessWide,
            base: majit_rlib::cache::Cache::EMPTY,
        },
        sys_state: crate::module::sys::state::SysState::new(),
        class_dict_strategy: crate::objspace::std::classdict::ClassDictStrategy::new(
            SpaceHandle::ProcessWide,
        ),
        gateway_cache: crate::gateway::GatewayCache::new(SpaceHandle::ProcessWide),
        type_cache: crate::objspace::std::typeobject::TypeCache::new(SpaceHandle::ProcessWide),
        w_object: SpaceAttr::new(),
        w_type: SpaceAttr::new(),
        w_base_exception: SpaceAttr::new(),
        w_type_error: SpaceAttr::new(),
    };

    pub fn sys_state(&self) -> &crate::module::sys::state::SysState {
        &self.sys_state
    }

    pub fn class_dict_strategy(&self) -> &crate::objspace::std::classdict::ClassDictStrategy {
        &self.class_dict_strategy
    }

    pub fn gateway_cache(&self) -> &crate::gateway::GatewayCache {
        &self.gateway_cache
    }

    pub fn type_cache(&self) -> &crate::objspace::std::typeobject::TypeCache {
        &self.type_cache
    }

    /// `space.w_object`; null before `init_typeobjects` sets it.
    pub fn w_object(&self) -> PyObjectRef {
        self.w_object.get()
    }

    /// `space.w_type`; null before `init_typeobjects` sets it.
    pub fn w_type(&self) -> PyObjectRef {
        self.w_type.get()
    }

    /// `space.w_BaseException`; null before the exception is registered.
    pub fn w_base_exception(&self) -> PyObjectRef {
        self.w_base_exception.get()
    }

    /// `space.w_TypeError`; null before the exception is registered.
    pub fn w_type_error(&self) -> PyObjectRef {
        self.w_type_error.get()
    }

    /// The `setattr(self, 'w_' + typedef.name, w_type)` of
    /// `StdObjSpace.initialize` for `object` and `type`.
    pub(crate) fn set_w_object(&self, w_object: PyObjectRef) {
        self.w_object.set(w_object);
    }

    pub(crate) fn set_w_type(&self, w_type: PyObjectRef) {
        self.w_type.set(w_type);
    }

    /// `export_builtin_exceptions`: `setattr(self, "w_" + excname, w_exc)`
    /// for the exceptions the space reads by attribute.
    pub(crate) fn export_builtin_exception(&self, excname: &str, w_exc: PyObjectRef) {
        let attr = match excname {
            "BaseException" => &self.w_base_exception,
            "TypeError" => &self.w_type_error,
            _ => return,
        };
        attr.set(w_exc);
    }

    pub fn new() -> std::sync::Arc<Self> {
        let space = std::sync::Arc::new_cyclic(|space| Self {
            fromcache: InternalSpaceCache::new(SpaceHandle::Isolated(space.clone())),
            sys_state: crate::module::sys::state::SysState::new(),
            class_dict_strategy: crate::objspace::std::classdict::ClassDictStrategy::new(
                SpaceHandle::Isolated(space.clone()),
            ),
            gateway_cache: crate::gateway::GatewayCache::new(SpaceHandle::Isolated(space.clone())),
            type_cache: crate::objspace::std::typeobject::TypeCache::new(SpaceHandle::Isolated(
                space.clone(),
            )),
            w_object: SpaceAttr::new(),
            w_type: SpaceAttr::new(),
            w_base_exception: SpaceAttr::new(),
            w_type_error: SpaceAttr::new(),
        });
        OBJECT_SPACE_ROOTS
            .lock()
            .push(std::sync::Arc::downgrade(&space));
        space
    }

    pub fn fromcache(&self, cls: SpaceCacheClass) -> SpaceCacheInstance {
        self.fromcache
            .getorbuild(cls)
            .unwrap_or_else(|_| panic!("recursive object-space cache construction"))
            .retain_owner()
    }

    pub fn walk_cache_roots(&self, forward: &mut dyn FnMut(&mut PyObjectRef)) {
        self.gateway_cache.walk_roots(forward);
        self.type_cache.walk_roots(forward);
        self.w_object.walk(forward);
        self.w_type.walk(forward);
        self.w_base_exception.walk(forward);
        self.w_type_error.walk(forward);
        self.fromcache.visit_values_mut(|cache| match cache {
            SpaceCacheInstance::ClassDictStrategy(cache) => cache.walk_roots(forward),
            SpaceCacheInstance::SysState(cache) => cache.walk_roots(forward),
        });
    }

    /// # Safety
    /// `definition` is an immutable live prebuilt TypeDef declaration.
    pub unsafe fn gettypeobject(
        &self,
        definition: *const pyre_object::typedef::TypeDef,
    ) -> Result<PyObjectRef, majit_rlib::cache::CacheError<crate::PyError>> {
        unsafe { self.type_cache.getorbuild(definition) }
    }
}

/// Process-wide `StdObjSpace` instance. Upstream the translated space is
/// a prebuilt captured by closures; this static is that instance, not a
/// `OnceLock` holder around it.
pub static OBJECT_SPACE: ObjSpace = ObjSpace::PREBUILT;

// Isolated test spaces, in addition to the process-wide prebuilt.
static OBJECT_SPACE_ROOTS: parking_lot::Mutex<Vec<std::sync::Weak<ObjSpace>>> =
    parking_lot::Mutex::new(Vec::new());

/// The process-wide object-space owner, shared by threads.
pub fn object_space() -> &'static ObjSpace {
    &OBJECT_SPACE
}

pub fn walk_object_space_cache_roots(forward: &mut dyn FnMut(&mut PyObjectRef)) {
    OBJECT_SPACE.walk_cache_roots(forward);
    OBJECT_SPACE_ROOTS.lock().retain(|owner| {
        if let Some(space) = owner.upgrade() {
            space.walk_cache_roots(forward);
            true
        } else {
            false
        }
    });
}

/// `rpython/rlib/rthread.py Lock` — the interp-level lock object
/// `allocate_lock` hands back.  Only `acquire`/`release` have callers here;
/// `is_acquired` / `acquire_timed` are ported when something needs them.
///
/// The blocking wait is a plain condvar wait rather than a GIL-dropping one:
/// pyre has no GIL to drop.  Nothing can wake a waiter yet either, since
/// `_thread.start_new_thread` runs its target on the caller's stack — so the
/// wait is reached only by a caller that contends with a lock the same OS
/// thread holds, which no import path does.  The shape is still the blocking
/// one so that the single-thread assumption is not baked into the callers.
pub struct Lock {
    acquired: parking_lot::Mutex<bool>,
    released: parking_lot::Condvar,
}

impl Lock {
    fn new() -> Self {
        Self {
            acquired: parking_lot::Mutex::new(false),
            released: parking_lot::Condvar::new(),
        }
    }

    /// `rthread.py acquire(flag)` — with `flag` set, wait until the lock
    /// is free and take it; otherwise take it only if it is free right now.
    /// Returns whether the lock is now held by the caller.
    pub fn acquire(&self, flag: bool) -> bool {
        let mut acquired = self.acquired.lock();
        while *acquired {
            if !flag {
                return false;
            }
            drop(acquired);
            // `rthread.acquire_timed(..., intr_flag=1)` enters the
            // external-call aroundstate before a potentially blocking native
            // lock wait.  In free-threaded pyre that transition removes this
            // mutator from the GC RUNNING census; otherwise an import-lock
            // waiter can prevent an STW collector from completing while the
            // lock owner is parked by that same STW.
            //
            // The lock is claimed only after the aroundstate is left again.
            // Leaving it is where a non-finalizing thread parks once teardown
            // has begun (`park_if_finalizing`), and a thread parked there must
            // not own the lock: the finalizing thread still takes the import
            // lock and the buffered-stream locks.
            {
                let _blocked = crate::module::thread::before_external_block();
                let mut waiting = self.acquired.lock();
                while *waiting {
                    self.released.wait(&mut waiting);
                }
            }
            acquired = self.acquired.lock();
        }
        *acquired = true;
        true
    }

    /// `rthread.py release` — `if c_thread_releaselock(...) != 0: raise
    /// error(...)`.  The check is live in every build upstream, so it is an
    /// `assert!` and not a `debug_assert!`: releasing a lock nobody holds must
    /// not fall through to the notify.  Every caller here releases only what it
    /// owns, which makes this an invariant of this crate rather than a
    /// Python-visible error.
    pub fn release(&self) {
        let mut acquired = self.acquired.lock();
        assert!(*acquired, "the lock was not previously acquired");
        *acquired = false;
        // Every waiter, because a woken one claims the lock only after
        // leaving the external-call state, and may park instead of claiming.
        self.released.notify_all();
    }
}

/// `pypy/interpreter/baseobjspace.py space.allocate_lock()`.
///
/// Upstream picks `rthread.dummy_lock` when the build has no `thread` module;
/// pyre always registers `_thread`, so the `rthread.allocate_lock()` branch
/// (`baseobjspace.py`) is the one taken.  `CannotHaveLock`
/// (`baseobjspace.py`) guards the translating-but-not-translated case,
/// which pyre never occupies, so this cannot fail.
///
/// The returned pointer is deliberately leaked: locks live for the process,
/// and freeing one while another thread could be waiting on it is unsound.
pub fn allocate_lock() -> *mut Lock {
    Box::into_raw(Box::new(Lock::new()))
}

/// Whether `needle` is pointer-identical to any entry of an installed MRO
/// slice.  Shared by [`issubtype_w`] and
/// [`crate::typedef::check_user_subclass`].
pub(crate) fn mro_contains(mro: &[PyObjectRef], needle: PyObjectRef) -> bool {
    mro.iter().any(|&t| std::ptr::eq(t, needle))
}

/// pypy/interpreter/baseobjspace.py `issubtype_w` — `cls` is in
/// `w_type.mro_w`. Iterates the installed MRO (`typeobject.py:1640-1644
/// _issubtype`: `w_type in w_sub.mro_w`); a type whose MRO is not yet
/// installed (`mro_ptr` null / `not hasmro`) takes the
/// [`issubtype_slow_and_wrong`] base-chain walk.
pub(crate) unsafe fn issubtype_w(w_type: PyObjectRef, cls: PyObjectRef) -> bool {
    if w_type.is_null() {
        return false;
    }
    // PyPy's issubtype_w is only valid for type objects.  Use the same
    // object-space test as abstractinst.py (`space.isinstance_w(...,
    // space.w_type)`) instead of peeking at Rust layout internals.
    if !is_type_like_w(w_type) {
        return false;
    }
    // One owner for `_issubtype`: under the JIT this registered
    // `dont_look_inside` helper is the residual scan inside PyPy's
    // `_pure_issubtype`; it also owns the partially-initialized slow path.
    pyre_object::w_type_issubtype(w_type, cls)
}

/// JIT walker accessor for `issubtype_w` without exposing the internal helper
/// as a general cross-crate API.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn jit_issubtype_w(w_type: PyObjectRef, cls: PyObjectRef) -> bool {
    unsafe { issubtype_w(w_type, cls) }
}

/// JIT walker accessor for abstractinst.py's `space.isinstance_w(obj, type)`
/// class test.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn jit_is_type_like_w(obj: PyObjectRef) -> bool {
    unsafe { is_type_like_w(obj) }
}

/// `typeobject.py _issubtype_slow_and_wrong` — the subtype test
/// for a partially-initialised `w_type` whose MRO is not yet installed
/// (reached only from a custom `MetaCls.mro()`).  Walks the best-base chain
/// rather than the MRO; deliberately broken wrt. multiple inheritance,
/// matching CPython.
///
/// `dont_look_inside`: the cold walk bottoms out in `find_best_base`'s
/// `w_tuple_items_copy_as_vec` `Vec` iteration, opaque to the annotator, and
/// returns a single-word `bool`, so it residualises behind one boundary —
/// keeping the hot cached-MRO branch of [`issubtype_w`] a pure typed-slice
/// iteration instead of a `<slice> ∪ <opaque Vec>` phi merge.
#[majit_macros::dont_look_inside]
pub(crate) unsafe fn issubtype_slow_and_wrong(w_type: PyObjectRef, cls: PyObjectRef) -> bool {
    let mut w_cls = w_type;
    while !w_cls.is_null() {
        if std::ptr::eq(w_cls, cls) {
            return true;
        }
        w_cls = pyre_object::typeobject::w_type_get_best_base(w_cls);
    }
    false
}

/// pypy/interpreter/baseobjspace.py `exception_is_valid_obj_as_class_w`.
///
///   def exception_is_valid_obj_as_class_w(self, w_obj):
///       if not self.isinstance_w(w_obj, self.w_type):
///           return False
///       return self.issubtype_w(w_obj, self.w_BaseException)
///
/// Canonical `BaseException` comes from the EXC_CLASS_REGISTRY populated at
/// `make_exc_type` time — not from the mutable builtins dict — so a user
/// rebinding `builtins.BaseException` cannot redirect the gate.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn exception_is_valid_obj_as_class_w(w_obj: PyObjectRef) -> bool {
    if !is_type_like_w(w_obj) {
        return false;
    }
    let Some(base_exc) = cached_base_exception() else {
        return false;
    };
    issubtype_w(w_obj, base_exc)
}

/// pypy/interpreter/baseobjspace.py `exception_is_valid_class_w`.
///
///   def exception_is_valid_class_w(self, w_cls):
///       return self.issubtype_w(w_cls, self.w_BaseException)
///
/// Like `exception_is_valid_obj_as_class_w` but skips the
/// `isinstance_w(w_cls, w_type)` precheck — the caller already knows
/// `w_cls` is a class object.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn exception_is_valid_class_w(w_cls: PyObjectRef) -> bool {
    let Some(base_exc) = cached_base_exception() else {
        return false;
    };
    issubtype_w(w_cls, base_exc)
}

/// `space.w_BaseException`, set when `make_exc_type` registers the class
/// (`export_builtin_exceptions`); `None` before that.
fn cached_base_exception() -> Option<PyObjectRef> {
    let base_exc = object_space().w_base_exception();
    if base_exc.is_null() {
        None
    } else {
        Some(base_exc)
    }
}

/// `space.w_TypeError`, set the same way as [`cached_base_exception`].
fn cached_type_error() -> Option<PyObjectRef> {
    let cls = object_space().w_type_error();
    if cls.is_null() { None } else { Some(cls) }
}

/// pypy/interpreter/baseobjspace.py `exception_getclass`.
///
///   def exception_getclass(self, w_obj):
///       return self.type(w_obj)
pub fn exception_getclass(w_obj: PyObjectRef) -> PyObjectRef {
    // Spelled as a `match` rather than `map_or`: the closure operand reaches
    // the codewriter as a synthetic transparent constructor with no lowering,
    // which stands as an un-lowered helper blocker in every body that calls
    // this — `exc_info_direct` among them.
    match crate::typedef::r#type(w_obj) {
        Some(p) => p.as_ptr(),
        None => pyre_object::PY_NULL,
    }
}

/// `interp_exceptions.py W_SyntaxError` direct slot reader.
///
/// PyPy's `descr_init` writes the eight `w_*` fields before forwarding the
/// original positional arguments to `W_BaseException.descr_init`; reads do
/// not reconstruct them from `args_w` or the instance dictionary.
pub(crate) fn syntax_error_attr(obj: PyObjectRef, name: &str) -> PyObjectRef {
    let value = unsafe {
        match name {
            "msg" => pyre_object::interp_exceptions::w_exception_get_syntax_msg(obj),
            "filename" => pyre_object::interp_exceptions::w_exception_get_syntax_filename(obj),
            "lineno" => pyre_object::interp_exceptions::w_exception_get_syntax_lineno(obj),
            "offset" => pyre_object::interp_exceptions::w_exception_get_syntax_offset(obj),
            "text" => pyre_object::interp_exceptions::w_exception_get_syntax_text(obj),
            "end_lineno" => pyre_object::interp_exceptions::w_exception_get_syntax_end_lineno(obj),
            "end_offset" => pyre_object::interp_exceptions::w_exception_get_syntax_end_offset(obj),
            "print_file_and_line" => {
                pyre_object::interp_exceptions::w_exception_get_syntax_print_file_and_line(obj)
            }
            "_metadata" => pyre_object::interp_exceptions::w_exception_get_syntax_metadata(obj),
            _ => PY_NULL,
        }
    };
    if value.is_null() { w_none() } else { value }
}

/// pypy/interpreter/baseobjspace.py `exception_issubclass_w`.
///
///   def exception_issubclass_w(self, w_cls1, w_cls2):
///       return self.issubtype_w(w_cls1, w_cls2)
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn exception_issubclass_w(w_cls1: PyObjectRef, w_cls2: PyObjectRef) -> bool {
    unsafe { issubtype_w(w_cls1, w_cls2) }
}

/// abstractinst.py `_get_bases(space, w_cls)`.
/// Returns `Some(bases_tuple)` when `getattr(w_cls, "__bases__")` exists
/// and is a tuple, `None` when the attribute is missing or not a tuple.
/// AttributeError is swallowed; other errors propagate.
fn _get_bases(w_cls: PyObjectRef) -> Result<Option<PyObjectRef>, PyError> {
    let w_bases = match getattr_str(w_cls, "__bases__") {
        Ok(b) => b,
        Err(e) if e.kind == PyErrorKind::AttributeError => return Ok(None),
        Err(e) => return Err(e),
    };
    if w_bases.is_null() {
        return Ok(None);
    }
    if unsafe { is_tuple(w_bases) } {
        Ok(Some(w_bases))
    } else {
        Ok(None)
    }
}

/// abstractinst.py `abstract_isclass_w(space, w_obj)`.
fn abstract_isclass_w(w_obj: PyObjectRef) -> Result<bool, PyError> {
    Ok(_get_bases(w_obj)?.is_some())
}

/// abstractinst.py `check_class(space, w_obj, msg)`. Raises
/// `TypeError(msg)` when `w_obj` lacks a tuple-valued `__bases__`.
///
/// The `, got %T` suffix upstream appends is deliberately dropped: every
/// caller passes the 3.14 message text, which names the accepted kinds
/// instead of the rejected argument's type.
fn check_class(w_obj: PyObjectRef, msg: &str) -> Result<(), PyError> {
    if !abstract_isclass_w(w_obj)? {
        return Err(PyError::type_error(msg.to_string()));
    }
    Ok(())
}

/// abstractinst.py `p_recursive_isinstance_type_w`. Assumes
/// `w_type` is a real type object: tries the MRO walk via `isinstance_w`
/// first, then consults `w_inst.__class__` to honour any custom class
/// override.
pub(crate) unsafe fn p_recursive_isinstance_type_w(
    mut w_inst: PyObjectRef,
    mut w_type: PyObjectRef,
) -> Result<bool, PyError> {
    if isinstance_w(w_inst, w_type) {
        return Ok(true);
    }
    let w_abstractclass = match pyre_object::with_roots!(w_inst, w_type => getattr_str(w_inst, "__class__"))
    {
        Ok(cls) => cls,
        Err(e) if e.kind == PyErrorKind::AttributeError => return Ok(false),
        Err(e) => return Err(e),
    };
    let w_inst_type = crate::typedef::r#type(w_inst).map_or(pyre_object::PY_NULL, |p| p.as_ptr());
    if !std::ptr::eq(w_abstractclass, w_inst_type) && is_type_like_w(w_abstractclass) {
        return Ok(issubtype_w(w_abstractclass, w_type));
    }
    Ok(false)
}

/// abstractinst.py `p_recursive_isinstance_w`. The Py3 port drops
/// the `W_ClassObject`/`W_ObjectObject` Py2 fast path. Validates
/// `w_cls` via `check_class()` before falling back to the abstract
/// `__class__` / `__bases__` walk.
unsafe fn p_recursive_isinstance_w(
    mut w_inst: PyObjectRef,
    mut w_cls: PyObjectRef,
) -> Result<bool, PyError> {
    if is_type_like_w(w_cls) {
        return p_recursive_isinstance_type_w(w_inst, w_cls);
    }
    pyre_object::with_roots!(w_cls, w_inst => check_class(
        w_cls,
        "isinstance() arg 2 must be a type, a tuple of types, or a union",
    ))?;
    let w_abstractclass = match pyre_object::with_roots!(w_cls => getattr_str(w_inst, "__class__"))
    {
        Ok(cls) => cls,
        Err(e) if e.kind == PyErrorKind::AttributeError => return Ok(false),
        Err(e) => return Err(e),
    };
    p_abstract_issubclass_w(w_abstractclass, w_cls)
}

/// abstractinst.py p_recursive_isinstance_w / 154-156:
/// `space.isinstance_w(obj, space.w_type)`.
///
/// This deliberately goes through pyre's object-space `isinstance_w`,
/// which consults the Python-level class (`w_class` / W_TypeObject MRO).
/// Do not replace it with `pyre_object::is_type_or_subtype()`: that helper
/// inspects the static Rust `PyType` tag and is not the RPython data path.
unsafe fn is_type_like_w(obj: PyObjectRef) -> bool {
    let w_type = crate::typedef::w_type();
    !w_type.is_null() && isinstance_w(obj, w_type)
}

/// `space.isinstance_w(w_obj, space.w_text)` — PyPy parity helper for
/// accepting `str` and any `str` subclass.  Used by `function.py:464`
/// `fset_func_name` and similar gateway-level type checks where the
/// upstream test is `isinstance_w(..., w_text)`, not exact-type
/// equality.  pyre's `pyre_object::is_str` only matches the exact
/// `STR_TYPE` tag and so rejects `class MyStr(str): pass` instances
/// — this helper fills in the MRO walk.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn isinstance_str_w(obj: PyObjectRef) -> bool {
    if obj.is_null() {
        return false;
    }
    if pyre_object::is_str(obj) {
        return true;
    }
    if let Some(str_type) = crate::typedef::gettypefor(&pyre_object::STR_TYPE) {
        return isinstance_w(obj, str_type.as_ptr());
    }
    false
}

/// `space.isinstance_w(w_obj, space.w_int)` — PyPy parity helper for
/// `space.int_w` callers that should accept `int` and any `int`
/// subclass (e.g. `bool` and user-defined `class MyInt(int): pass`).
/// pyre's `pyre_object::is_int` matches `int` + `bool` only.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn isinstance_int_w(obj: PyObjectRef) -> bool {
    if obj.is_null() {
        return false;
    }
    if pyre_object::is_int(obj) {
        return true;
    }
    if let Some(int_type) = crate::typedef::gettypefor(&pyre_object::INT_TYPE) {
        return isinstance_w(obj, int_type.as_ptr());
    }
    false
}

/// `space.isinstance_w(w_obj, space.w_bytes)` — accepts `bytes` and
/// any `bytes` subclass.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn isinstance_bytes_w(obj: PyObjectRef) -> bool {
    if obj.is_null() {
        return false;
    }
    if pyre_object::is_bytes(obj) {
        return true;
    }
    if let Some(bytes_type) = crate::typedef::gettypefor(&pyre_object::BYTES_TYPE) {
        return isinstance_w(obj, bytes_type.as_ptr());
    }
    false
}

/// `space.charbuf_w` admits anything implementing the buffer protocol;
/// PyPy's `W_UnicodeDecodeError.descr_init` (`interp_exceptions.py`)
/// uses it for `w_object` and then coerces to `bytes`.  In pyre the
/// concrete buffer producers are `bytes` and `bytearray` (incl.
/// subclasses); this helper accepts either.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn isinstance_bytes_like_w(obj: PyObjectRef) -> bool {
    if obj.is_null() {
        return false;
    }
    if pyre_object::is_bytes_like(obj) {
        return true;
    }
    if let Some(bytes_type) = crate::typedef::gettypefor(&pyre_object::BYTES_TYPE)
        && isinstance_w(obj, bytes_type.as_ptr())
    {
        return true;
    }
    if let Some(bytearray_type) = crate::typedef::gettypefor(&pyre_object::BYTEARRAY_TYPE) {
        return isinstance_w(obj, bytearray_type.as_ptr());
    }
    false
}

/// `space.isinstance_w(w_obj, space.w_list)` — accepts `list` and any
/// `list` subclass.  pyre's `pyre_object::is_list` matches the exact
/// `LIST_TYPE` tag only.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn isinstance_list_w(obj: PyObjectRef) -> bool {
    if obj.is_null() {
        return false;
    }
    if pyre_object::is_list(obj) {
        return true;
    }
    if let Some(list_type) = crate::typedef::gettypefor(&pyre_object::LIST_TYPE) {
        return isinstance_w(obj, list_type.as_ptr());
    }
    false
}

/// `space.isinstance_w(w_obj, space.w_bytearray)` — accepts `bytearray` and any
/// `bytearray` subclass.  `pyre_object::is_bytearray` matches the exact tag.
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn isinstance_bytearray_w(obj: PyObjectRef) -> bool {
    if obj.is_null() {
        return false;
    }
    if unsafe { pyre_object::bytearrayobject::is_bytearray(obj) } {
        return true;
    }
    if let Some(bytearray_type) = crate::typedef::gettypefor(&pyre_object::BYTEARRAY_TYPE) {
        return unsafe { isinstance_w(obj, bytearray_type.as_ptr()) };
    }
    false
}

/// `space.isinstance_w(w_obj, space.w_dict)` — accepts `dict` and any `dict`
/// subclass.  `pyre_object::is_dict` matches the exact tag and the module-dict
/// sibling only.
///
/// A `list` subclass instance is a `W_ListObject` carrying the subclass in
/// `w_class`, so the exact tag already answers for it; a `dict` subclass
/// instance is not a dict at all but an object holding one
/// (`typedef.rs dict_descr_new`), which is why this one is needed where
/// [`isinstance_list_w`] is mostly a formality.  Reaching the mapping itself is
/// [`crate::type_methods::resolve_dict_backing`].
/// # Safety
/// The caller must uphold every validity, runtime-type, aliasing, and lifetime
/// invariant required by the object and pointer arguments for the entire call.
pub unsafe fn isinstance_dict_w(obj: PyObjectRef) -> bool {
    if obj.is_null() {
        return false;
    }
    if pyre_object::is_dict(obj) {
        return true;
    }
    if let Some(dict_type) = crate::typedef::gettypefor(&pyre_object::DICT_TYPE) {
        return isinstance_w(obj, dict_type.as_ptr());
    }
    false
}

/// abstractinst.py `p_abstract_issubclass_w`. Walks
/// `w_derived.__bases__` looking for an identity match with `w_cls`.
/// Recursion is bounded by avoiding the last entry of each `__bases__`
/// tuple — that one is followed by re-entering the loop.
///
/// `@jit.unroll_safe` (abstractinst.py): the `__bases__` walk is a loop, and
/// `look_inside_graph` (policy.py) rejects a loop-bearing graph. The hint
/// clears `contains_loop` before that test, so the graph stays in the candidate
/// set, mints a jitcode, and the walker unrolls the walk instead of leaving the
/// call an opaque residual.
#[majit_macros::unroll_safe]
pub(crate) fn p_abstract_issubclass_w(
    w_derived: PyObjectRef,
    mut w_cls: PyObjectRef,
) -> Result<bool, PyError> {
    let mut w_derived = w_derived;
    loop {
        if pyre_object::with_roots!(w_cls, w_derived => is_w(w_derived, w_cls)) {
            return Ok(true);
        }
        let mut w_bases = match pyre_object::with_roots!(w_cls => _get_bases(w_derived))? {
            Some(b) => b,
            None => return Ok(false),
        };
        let n = unsafe { w_tuple_len(w_bases) };
        if n == 0 {
            return Ok(false);
        }
        let last_index = n - 1;
        for i in 0..last_index {
            let base = match unsafe { w_tuple_getitem(w_bases, i as i64) } {
                Some(b) => b,
                None => return Ok(false),
            };
            if pyre_object::with_roots!(w_bases, w_cls => p_abstract_issubclass_w(base, w_cls))? {
                return Ok(true);
            }
        }
        w_derived = match unsafe { w_tuple_getitem(w_bases, last_index as i64) } {
            Some(b) => b,
            None => return Ok(false),
        };
    }
}

/// abstractinst.py `p_recursive_issubclass_w`. The both-types
/// fast path is the common case; otherwise both arguments are validated
/// via `check_class()` before entering the abstract walk.
pub(crate) unsafe fn p_recursive_issubclass_w(
    mut w_derived: PyObjectRef,
    mut w_cls: PyObjectRef,
) -> Result<bool, PyError> {
    // A parameterized GenericAlias delegates ordinary attributes (including
    // `__bases__`) to its origin, but is not itself a class.  CPython's
    // abstract subclass check rejects it as argument 1 before the legacy
    // tuple-valued-`__bases__` fallback can mistake it for the origin.
    if pyre_object::is_generic_alias(w_derived) {
        return Err(PyError::type_error("issubclass() arg 1 must be a class"));
    }
    if is_type_like_w(w_cls) && is_type_like_w(w_derived) {
        return Ok(issubtype_w(w_derived, w_cls));
    }
    pyre_object::with_roots!(w_cls, w_derived => check_class(w_derived, "issubclass() arg 1 must be a class"))?;
    pyre_object::with_roots!(w_cls, w_derived => check_class(
        w_cls,
        "issubclass() arg 2 must be a class, a tuple of classes, or a union",
    ))?;
    p_abstract_issubclass_w(w_derived, w_cls)
}

/// pypy/module/__builtin__/abstractinst.py:91-122
/// `abstract_isinstance_w(space, w_obj, w_klass_or_tuple, allow_override=True)`.
/// Handles tuple/union recursion, the `__instancecheck__` override
/// looked up via `space.lookup(w_klass_or_tuple, "__instancecheck__")`,
/// then the abstract `__class__`/`__bases__` walk.
///
/// `@jit.unroll_safe` (abstractinst.py): the tuple/union classinfo walk is a
/// loop, and `look_inside_graph` (policy.py) rejects a loop-bearing graph.
/// The hint clears `contains_loop` before that test, so the graph stays in the
/// candidate set, mints a jitcode, and the walker unrolls the walk instead of
/// leaving the call an opaque residual.
#[majit_macros::unroll_safe]
pub fn isinstance(obj: PyObjectRef, classinfo: PyObjectRef) -> Result<bool, PyError> {
    // Nested tuple / union classinfo recurses in native Rust with no
    // Python frame push, so guard the C stack here or a deep classinfo
    // blows it before any frame-level check fires.
    crate::stack_check::stack_check()?;
    unsafe {
        // abstractinst.py:104-106 — quick exact-type test.
        if let Some(t) = crate::typedef::r#type(obj)
            && std::ptr::eq(t.as_ptr(), classinfo)
        {
            return Ok(true);
        }
        // abstractinst.py:108-114 — tuple recursion.
        if is_tuple(classinfo) {
            // The recursive `isinstance` re-enters Python (`__instancecheck__`)
            // and may collect; `obj` and the classinfo tuple are raw locals, so
            // pin them on the shadow stack across the walk.
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, classinfo]);
            let info_slot = obj_slot + 1;
            let n = w_tuple_len(pyre_object::gc_roots::shadow_stack_get(info_slot));
            for i in 0..n {
                if let Some(c) =
                    w_tuple_getitem(pyre_object::gc_roots::shadow_stack_get(info_slot), i as i64)
                    && isinstance(pyre_object::gc_roots::shadow_stack_get(obj_slot), c)?
                {
                    return Ok(true);
                }
            }
            return Ok(false);
        }
        // PEP 604 `X | Y` union recursion — lib_pypy/_pypy_generic_alias.py.
        if pyre_object::is_union(classinfo) {
            let union_args = pyre_object::w_union_get_args(classinfo);
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, union_args]);
            let args_slot = obj_slot + 1;
            let n = w_tuple_len(pyre_object::gc_roots::shadow_stack_get(args_slot));
            for i in 0..n {
                if let Some(c) =
                    w_tuple_getitem(pyre_object::gc_roots::shadow_stack_get(args_slot), i as i64)
                    && isinstance(pyre_object::gc_roots::shadow_stack_get(obj_slot), c)?
                {
                    return Ok(true);
                }
            }
            return Ok(false);
        }
        // abstractinst.py:117-124 — `__instancecheck__` override
        // (`allow_override=True`). PyPy uses
        // `space.lookup(w_klass_or_tuple, "__instancecheck__")`, which
        // is a metaclass-MRO lookup (`lookup_in_type(type(cls), …)`),
        // not `getattr(cls, …)`. The distinction matters for the
        // weakproxy proxy_typedef_dict row: pyre's `getattr` runs the
        // `force()` fast path at entry and would dereference the proxy
        // before the typedef row ever gets a chance to fire. Going
        // through `lookup_in_type` on `type(classinfo)` keeps the
        // proxy's typedef wrapper installed via `proxy_typedef_dict`
        // visible. For a real type object the metaclass is `type`, which
        // carries an `__instancecheck__` slot, so an ordinary `isinstance(x,
        // C)` takes the descriptor call here rather than the
        // `p_recursive_isinstance_w` fall-through below; that slot is the one
        // that calls back into `p_recursive_isinstance_type_w`, so the two
        // paths agree.
        let _isinstance_roots = pyre_object::gc_roots::push_roots();
        let isinstance_base = pyre_object::gc_roots::pin_roots(&[obj, classinfo]);
        let obj = || pyre_object::gc_roots::shadow_stack_get(isinstance_base);
        let classinfo = || pyre_object::gc_roots::shadow_stack_get(isinstance_base + 1);
        if let Some(cls_type) = crate::typedef::r#type(classinfo())
            && let Some(check) = lookup_in_type(cls_type.as_ptr(), "__instancecheck__")
        {
            // abstractinst.py:122 `space.get_and_call_function(w_check,
            // w_klass_or_tuple, w_obj)` — bind the descriptor to
            // `classinfo` before calling with `obj`.
            let check_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(check);
            let result = get_and_call_function(
                pyre_object::gc_roots::shadow_stack_get(check_slot),
                classinfo(),
                cls_type.as_ptr(),
                &[obj()],
            )?;
            return is_true(result);
        }
        p_recursive_isinstance_w(obj(), classinfo())
    }
}

/// pypy/module/__builtin__/abstractinst.py:169-198
/// `abstract_issubclass_w(space, w_derived, w_klass_or_tuple, allow_override=True)`.
/// Tuple/union recursion, `__subclasscheck__` override looked up on
/// `type(classinfo)`, then the abstract `__bases__` walk.
///
/// `@jit.unroll_safe` (abstractinst.py): the tuple/union classinfo walk is a
/// loop, and `look_inside_graph` (policy.py) rejects a loop-bearing graph.
/// The hint clears `contains_loop` before that test, so the graph stays in the
/// candidate set, mints a jitcode, and the walker unrolls the walk instead of
/// leaving the call an opaque residual.
#[majit_macros::unroll_safe]
pub fn issubclass(derived: PyObjectRef, classinfo: PyObjectRef) -> Result<bool, PyError> {
    // Nested tuple / union classinfo recurses in native Rust with no
    // Python frame push, so guard the C stack here or a deep classinfo
    // blows it before any frame-level check fires.
    crate::stack_check::stack_check()?;
    unsafe {
        // abstractinst.py:181-187 — tuple recursion.
        if is_tuple(classinfo) {
            // The recursive `issubclass` re-enters Python (`__subclasscheck__`)
            // and may collect; `derived` and the classinfo tuple are raw locals,
            // so pin them on the shadow stack across the walk.
            let _roots = pyre_object::gc_roots::push_roots();
            let derived_slot = pyre_object::gc_roots::pin_roots(&[derived, classinfo]);
            let info_slot = derived_slot + 1;
            let n = w_tuple_len(pyre_object::gc_roots::shadow_stack_get(info_slot));
            for i in 0..n {
                if let Some(c) =
                    w_tuple_getitem(pyre_object::gc_roots::shadow_stack_get(info_slot), i as i64)
                    && issubclass(pyre_object::gc_roots::shadow_stack_get(derived_slot), c)?
                {
                    return Ok(true);
                }
            }
            return Ok(false);
        }
        if pyre_object::is_union(classinfo) {
            let union_args = pyre_object::w_union_get_args(classinfo);
            let _roots = pyre_object::gc_roots::push_roots();
            let derived_slot = pyre_object::gc_roots::pin_roots(&[derived, union_args]);
            let args_slot = derived_slot + 1;
            let n = w_tuple_len(pyre_object::gc_roots::shadow_stack_get(args_slot));
            for i in 0..n {
                if let Some(c) =
                    w_tuple_getitem(pyre_object::gc_roots::shadow_stack_get(args_slot), i as i64)
                    && issubclass(pyre_object::gc_roots::shadow_stack_get(derived_slot), c)?
                {
                    return Ok(true);
                }
            }
            return Ok(false);
        }
        // abstractinst.py:190-196 — `__subclasscheck__` override.
        // Same `lookup_in_type(type(classinfo), …)` rationale as
        // `isinstance` above.
        let _issubclass_roots = pyre_object::gc_roots::push_roots();
        let issubclass_base = pyre_object::gc_roots::pin_roots(&[derived, classinfo]);
        let derived = || pyre_object::gc_roots::shadow_stack_get(issubclass_base);
        let classinfo = || pyre_object::gc_roots::shadow_stack_get(issubclass_base + 1);
        if let Some(cls_type) = crate::typedef::r#type(classinfo())
            && let Some(check) = lookup_in_type(cls_type.as_ptr(), "__subclasscheck__")
        {
            // abstractinst.py:195 `space.get_and_call_function(w_check,
            // w_klass_or_tuple, w_derived)` — bind the descriptor to
            // `classinfo` before calling with `derived`.
            let check_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(check);
            let result = get_and_call_function(
                pyre_object::gc_roots::shadow_stack_get(check_slot),
                classinfo(),
                cls_type.as_ptr(),
                &[derived()],
            )?;
            return is_true(result);
        }
        p_recursive_issubclass_w(derived(), classinfo())
    }
}

/// Test if an object is truthy (for branch conditions).
///
/// Python truthiness rules:
/// - None → false
/// - bool → its value
/// - int → nonzero

/// `baseobjspace.py isabstractmethod_w`:
///
/// ```python
/// def isabstractmethod_w(self, w_obj):
///     try:
///         w_result = self.getattr(w_obj, self.newtext("__isabstractmethod__"))
///     except OperationError as e:
///         if e.match(self, self.w_AttributeError):
///             return False
///         raise
///     return self.is_true(w_result)
/// ```
///
/// Catches the AttributeError arm of the upstream try/except and
/// reraises any other PyError so the caller (typedef descr_isabstract
/// for staticmethod / classmethod) can propagate it.
pub fn isabstractmethod_w(obj: PyObjectRef) -> Result<bool, crate::PyError> {
    match getattr_str(obj, "__isabstractmethod__") {
        Ok(w_result) => Ok(is_true(w_result)?),
        Err(e) if matches!(e.kind, crate::PyErrorKind::AttributeError) => Ok(false),
        Err(e) => Err(e),
    }
}

/// Resolve a special method `name` on `obj`'s type, returning it (with the
/// owning `w_type` for `get_and_call_function` binding) only when the object
/// is a builtin subclass that *overrides* it — i.e. the MRO resolution
/// differs from the implementation the builtin layout type itself registers.
///
/// The by-layout fast paths (`space.is_true` / `len` / `getitem` / `compare`
/// / …) are the inherited builtin behaviour; a subclass that does not
/// override the method must keep using them.  Crucially, the builtin
/// typedef slots delegate back into these very `space` entry points
/// (`list.__getitem__` → `space.getitem`, `int.__eq__` → `compare`), so
/// dispatching the *inherited* slot would recurse forever — this helper
/// returns `None` for the inherited case so the caller takes the fast path,
/// and only returns `Some` for a genuine user override (whose body is user
/// code, not a re-entry).
///
/// Returns `None` for exact builtins, for absent methods, and for inherited
/// builtin slots.
///
/// # Safety
/// `obj` must be a valid `PyObjectRef`.
pub(crate) unsafe fn subclass_special_override(
    obj: PyObjectRef,
    name: &str,
) -> Option<(PyObjectRef, PyObjectRef)> {
    // Do not pin at the head: `pin_root` / `shadow_stack_get` are
    // `dont_look_inside`, and a residual on the exact-builtin return is
    // recorded by every walker that descends this body (`_len` /
    // `builtin_len_descent`, getitem, binop). Exact builtins never
    // collect here. MayForce C ABI copies are published in the `jit_*`
    // shims. Publish only on the override-lookup path, which can
    // allocate, then reload `obj` before reading `ob_type`.
    if pyre_object::is_exact_builtin_instance(obj) {
        return None;
    }
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::shadow_stack_len();
    let obj = pyre_object::gc_roots::pin_root(obj);
    let w_type = crate::typedef::r#type(obj)?;
    let method = lookup_in_type_where(w_type.as_ptr(), name)?;
    // The builtin layout type for `obj` — the canonical type object for its
    // `ob_type`.  When the MRO resolution matches that type's own slot the
    // method is inherited, not overridden.
    let obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
    let base = pyre_object::get_instantiate(&*(*obj).ob_type);
    if !base.is_null()
        && let Some(inherited) = lookup_in_type_where(base, name)
        && std::ptr::eq(inherited, method)
    {
        return None;
    }
    Some((method, w_type.as_ptr()))
}

/// descroperation.py `is_true`.
///
/// ```python
/// def is_true(space, w_obj):
///     w_descr = space.lookup(w_obj, "__bool__")
///     if w_descr is None:
///         w_descr = space.lookup(w_obj, "__len__")
///         if w_descr is None:
///             return True
///         w_res = space.get_and_call_function(w_descr, w_obj)
///         return space._check_len_result(space.index(w_res)) != 0
///     w_res = space.get_and_call_function(w_descr, w_obj)
///     if space.is_w(w_res, space.w_False): return False
///     if space.is_w(w_res, space.w_True):  return True
///     raise oefmt(space.w_TypeError,
///                 "__bool__ should return bool, returned %T", w_obj)
/// ```
///
/// A builtin subclass overriding `__bool__` / `__len__` is detected by
/// [`subclass_special_override`] and dispatched first. The leading built-in
/// fast paths then short-circuit the `lookup` + call machinery for exact
/// builtins (and non-overriding subclasses, whose inherited truthiness is
/// the by-layout result). Only objects matching no fast path reach the
/// generic tail, which consults `__bool__` then `__len__`, where the call
/// exceptions — and the non-bool-`__bool__` TypeError — propagate.
pub fn is_true(obj: PyObjectRef) -> Result<bool, PyError> {
    // objspace.py is_true: a shortcut for performance.
    if unsafe { is_bool(obj) } {
        return Ok(unsafe { w_bool_get_value(obj) });
    }
    // descroperation.py is_true — `__bool__` (anywhere in the MRO) is consulted
    // before `__len__`.  An exact builtin's `__bool__` / `__len__` are the
    // inherited builtin slots, so its truthiness is computed by layout in
    // `is_true_slot`; any other object (builtin subclass or user instance)
    // takes the `lookup` path, where an inherited builtin `__bool__` is still
    // found and wins over an overridden `__len__`.  `obj` is a live W_Root,
    // as upstream's `w_obj` is, so no null test precedes the class read.
    if unsafe { is_exact_builtin_instance_nonnull(obj) } {
        return is_true_slot(obj);
    }
    is_true_lookup(obj)
}

/// descroperation.py — the `lookup` path of `is_true`: `__bool__`
/// first, then `__len__`, each bound via `get_and_call_function` so
/// descriptors are honored.  Used for builtin subclasses and user instances
/// (and by `is_true_slot` for an exact builtin that matched no by-layout fast
/// path).  An inherited builtin `__bool__` is found here and takes priority
/// over an overridden `__len__`.
///
/// Hidden: after a red `sys.modules` pointer the descent scan cannot
/// prove `is_exact_builtin_instance`, and inlining this path reaches
/// `get_and_call_function`, `space_index` closures, and the warning
/// formatter (`__majit_stringbuilder_new`).
#[majit_macros::dont_look_inside]
pub(crate) fn is_true_lookup(obj: PyObjectRef) -> Result<bool, PyError> {
    // `__bool__` / `__len__` run arbitrary Python. Pin the operand so a
    // collecting dunder cannot leave this function holding a from-space word.
    let _roots = pyre_object::gc_roots::push_roots();
    let _ = pyre_object::gc_roots::pin_root(obj);
    let obj_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    if let Some(w_type) =
        crate::typedef::r#type(unsafe { pyre_object::gc_roots::shadow_stack_get(obj_slot) })
    {
        if let Some(w_descr) = unsafe { lookup_in_type(w_type.as_ptr(), "__bool__") } {
            let w_res = unsafe {
                get_and_call_function(
                    w_descr,
                    pyre_object::gc_roots::shadow_stack_get(obj_slot),
                    w_type.as_ptr(),
                    &[],
                )
            }?;
            // The only instances of bool are `w_False` / `w_True`, so any
            // other box is the TypeError, and what it names is the type of
            // what `__bool__` RETURNED.  The docstring above transcribes
            // `%T` on `w_obj`, which is upstream's own slip -- it computes
            // `w_restype` on the line before and then does not use it.
            if unsafe { is_bool(w_res) } {
                return Ok(unsafe { w_bool_get_value(w_res) });
            }
            // Keep that `format!` off the look-inside graph:
            // `__majit_stringbuilder_new` is an un-lowered helper, and a red
            // `__bool__` result would otherwise decline every descent that has
            // already executed an effect (the `__import__` `sys.modules` read).
            return Err(bool_must_return_bool(w_res));
        }
        if let Some(w_descr) = unsafe { lookup_in_type(w_type.as_ptr(), "__len__") } {
            let w_res = unsafe {
                get_and_call_function(
                    w_descr,
                    pyre_object::gc_roots::shadow_stack_get(obj_slot),
                    w_type.as_ptr(),
                    &[],
                )
            }?;
            let w_index = space_index(w_res)?;
            return Ok(_check_len_result(w_index)? != 0);
        }
    }
    Ok(true)
}

/// One-word residual-call ABI for [`is_true_lookup`].
///
/// `Ok(false)` and a published error both answer 0. The residual is a
/// raising `dont_look_inside` call, so `GUARD_NO_EXCEPTION` after it
/// distinguishes them.
pub extern "C" fn is_true_lookup_jit_abi(obj: PyObjectRef) -> i64 {
    match is_true_lookup(obj) {
        Ok(value) => value as i64,
        Err(error) => crate::runtime_ops::jit_publish_residual_error(error),
    }
}

/// `descroperation.py` TypeError for a `__bool__` that did not return a bool,
/// naming the type of the returned object.  The message allocates, so it stays
/// off the look-inside graph.
#[majit_macros::dont_look_inside]
pub(crate) fn bool_must_return_bool(w_res: PyObjectRef) -> PyError {
    PyError::type_error(format!(
        "__bool__ should return bool, returned {}",
        object_functionstr_type_name(w_res),
    ))
}

/// One-word residual-call ABI for [`bool_must_return_bool`].
///
/// The helper only constructs an error; the bridge publishes it and
/// returns 0.
pub extern "C" fn bool_must_return_bool_jit_abi(obj: PyObjectRef) -> i64 {
    crate::runtime_ops::jit_publish_residual_error(bool_must_return_bool(obj))
}

/// Direct truthiness body for `is_true`: the by-layout fast paths for exact
/// builtins, falling back to `is_true_lookup`.  The builtin `int` / `float`
/// `__bool__` base slots bind here so that the lookup path can invoke them
/// (for non-overriding subclasses) without recursing through `is_true`.
pub(crate) fn is_true_slot(obj: PyObjectRef) -> Result<bool, PyError> {
    unsafe {
        if is_bool(obj) {
            return Ok(w_bool_get_value(obj));
        }
        if is_int(obj) {
            return Ok(w_int_get_value(obj) != 0);
        }
        if is_long(obj) {
            // longobject.py W_LongObject.descr_bool delegates to the rbigint
            // sign.  Cloning the Rust handle here becomes a fresh translated
            // GC payload (`jit_bigint_clone`) and comparing against a newly
            // materialized zero, neither of which exists in the RPython path.
            return Ok(w_long_get_value(obj).get_sign() != 0);
        }
        if is_float(obj) {
            return Ok(w_float_get_value(obj) != 0.0);
        }
        if pyre_object::is_complex(obj) {
            return Ok(pyre_object::w_complex_get_real(obj) != 0.0
                || pyre_object::w_complex_get_imag(obj) != 0.0);
        }
        if is_str(obj) {
            return Ok(w_str_len(obj) != 0);
        }
        if pyre_object::is_bytes(obj) {
            return Ok(pyre_object::w_bytes_len(obj) != 0);
        }
        if pyre_object::is_bytearray(obj) {
            return Ok(pyre_object::w_bytearray_len(obj) != 0);
        }
        if is_list(obj) {
            return Ok(w_list_len(obj) > 0);
        }
        if is_tuple(obj) {
            return Ok(w_tuple_len(obj) > 0);
        }
        if is_dict(obj) {
            return Ok(w_dict_len(obj) > 0);
        }
        if pyre_object::is_set_or_frozenset(obj) {
            return Ok(pyre_object::w_set_len(obj) > 0);
        }
        if pyre_object::is_w_range(obj) {
            return Ok(pyre_object::w_range_bool(obj));
        }
        if is_none(obj) {
            return Ok(false);
        }
    }
    // No by-layout fast path matched (an exact builtin without a layout
    // predicate): consult `__bool__` / `__len__` via the lookup path.
    is_true_lookup(obj)
}

// ── Subscript operations ─────────────────────────────────────────────

/// Normalize a slice to (start, stop, step) for a sequence of `length`.
///
/// PyPy: sliceobject.py descr_indices, mirroring CPython
/// `PySlice_Unpack` + `PySlice_AdjustIndices`. Handles negative `step`
/// (which CPython adjusts the start/stop bounds for separately from
/// positive `step`). Each bound is evaluated through `__index__`
/// (`_eval_slice_index`), so a `float` or other non-integer bound raises
/// `TypeError` rather than being read as a raw integer field.
pub(crate) unsafe fn normalize_slice(
    index: PyObjectRef,
    length: i64,
) -> Result<(i64, i64, i64), PyError> {
    // A null Ref for a slice operand is silently misread on wasm: `is_none(null)`
    // is false (no deref), so the null flows into `eval_slice_index` ->
    // `getindex_w`, which reads `ob_type` at guest offset 0 (valid linear memory
    // on wasm) and returns garbage instead of trapping. Trap loudly and name the
    // operand so a wasm run pins which Ref is null.
    assert!(
        !index.is_null(),
        "normalize_slice: slice object Ref is null (wasm offset-0 silent-null); length={length}"
    );
    let mut start_obj = w_slice_get_start(index);
    let mut stop_obj = w_slice_get_stop(index);
    let step_obj = w_slice_get_step(index);
    assert!(
        !start_obj.is_null(),
        "normalize_slice: slice.start Ref is null (wasm offset-0 silent-null); length={length}"
    );
    assert!(
        !stop_obj.is_null(),
        "normalize_slice: slice.stop Ref is null (wasm offset-0 silent-null); length={length}"
    );
    assert!(
        !step_obj.is_null(),
        "normalize_slice: slice.step Ref is null (wasm offset-0 silent-null); length={length}"
    );
    let step = if is_none(step_obj) {
        1
    } else {
        pyre_object::with_roots!(start_obj, stop_obj => crate::sliceobject::eval_slice_index(step_obj))?
    };
    if step == 0 {
        return Err(PyError::new(
            PyErrorKind::ValueError,
            "slice step cannot be zero",
        ));
    }
    let (lower, upper) = if step > 0 {
        (0, length)
    } else {
        (-1, length - 1)
    };
    let start = if is_none(start_obj) {
        if step > 0 { 0 } else { length - 1 }
    } else {
        let v =
            pyre_object::with_roots!(stop_obj => crate::sliceobject::eval_slice_index(start_obj))?;
        let v = if v < 0 { v.saturating_add(length) } else { v };
        v.max(lower).min(upper)
    };
    let stop = if is_none(stop_obj) {
        if step > 0 { length } else { -1 }
    } else {
        let v = crate::sliceobject::eval_slice_index(stop_obj)?;
        let v = if v < 0 { v.saturating_add(length) } else { v };
        v.max(lower).min(upper)
    };
    Ok((start, stop, step))
}

/// `descroperation.py get_and_call_function`.
///
/// ```python
/// def get_and_call_function(space, w_descr, w_obj, *args_w):
///     typ = type(w_descr)
///     if typ is Function or typ is FunctionWithFixedCode:
///         return w_descr.funccall(w_obj, *args_w)
///     else:
///         args = Arguments(space, list(args_w))
///         w_impl = space.get(w_descr, w_obj)
///         return space.call_args(w_impl, args)
/// ```
///
/// The `Function`/`FunctionWithFixedCode` fast path calls
/// `funccall(w_obj, *args_w)` — `w_obj` leads the positionals.  Pyre gives a
/// type-owned `FunctionWithFixedCode` the distinct public
/// `METHOD_DESCRIPTOR_TYPE`, but it retains this exact PyPy call shape.
/// `BuiltinFunction` (`BUILTIN_FUNCTION_TYPE`) is excluded because it binds
/// differently.  Every other descriptor is bound through `get` (`space.get`)
/// first, then called with `args_w` alone, so `@staticmethod` /
/// `@classmethod` / custom-descriptor dunders receive the arguments PyPy
/// gives them.
pub unsafe fn get_and_call_function(
    w_descr: PyObjectRef,
    w_obj: PyObjectRef,
    w_type: PyObjectRef,
    args_w: &[PyObjectRef],
) -> PyResult {
    if !w_descr.is_null()
        && (std::ptr::eq(
            unsafe { (*w_descr).ob_type },
            &crate::FUNCTION_TYPE as *const _,
        ) || std::ptr::eq(
            unsafe { (*w_descr).ob_type },
            &crate::METHOD_DESCRIPTOR_TYPE as *const _,
        ))
    {
        // `DescrOperation.get_and_call_function`'s fast path spells this
        // `w_descr.funccall(w_obj, *args_w)`.  Arity 0..=4 is unrolled the
        // way `function.py funccall` specialises `BuiltinCodeN.fastcall_N`
        // — a stack array, not a `Vec`, so the interpreter does not
        // allocate per dunder and the tracer sees a constant-length call.
        // Longer calls still build the dynamic list `call_function` uses:
        // `with_capacity`/`push` lower to `newlist`/`append`.
        return match args_w.len() {
            0 => crate::function::funccall_result(w_descr, &[w_obj]),
            1 => crate::function::funccall_result(w_descr, &[w_obj, args_w[0]]),
            2 => crate::function::funccall_result(w_descr, &[w_obj, args_w[0], args_w[1]]),
            3 => {
                crate::function::funccall_result(w_descr, &[w_obj, args_w[0], args_w[1], args_w[2]])
            }
            _ => {
                let mut full = Vec::with_capacity(args_w.len() + 1);
                full.push(w_obj);
                full.extend_from_slice(args_w);
                crate::function::funccall_result(w_descr, full.as_slice())
            }
        };
    }
    // `get` dispatches `__get__`: a `property` getter and a user descriptor are
    // application-level Python, so a collection can land between the descriptor
    // lookup and the call below.  `w_obj` and `args_w` are raw addresses — the
    // latter a slice into the caller's Rust stack, which no root reaches — so
    // both would name pre-collection copies afterwards.  Pin the three
    // descriptor operands and every argument across the lookup, then rebuild the
    // argument list from the shadow stack.  Both slices are published before the
    // first `normalize_roots` so nothing is still invisible to a foreign
    // collector once this mutator starts entering safepoints.
    // Every slot access goes through the scope's cached root-stack cell: the
    // free `gc_roots` functions re-resolve the thread local per call, which on
    // Darwin is an out-of-line `_tlv_get_addr`, and this arm touches a slot
    // once per operand and once per argument.  The two slices are adjacent on
    // the stack, so the whole published set normalizes as one run.
    let _roots = pyre_object::gc_roots::push_roots();
    let base = _roots.publish(&[w_descr, w_obj, w_type]);
    let args_base = _roots.publish(args_w);
    _roots.normalize(base, 3 + args_w.len());
    let w_impl = unsafe { get(_roots.get(base), _roots.get(base + 1), _roots.get(base + 2)) }?
        .unwrap_or_else(|| _roots.get(base));
    // PyPy `descroperation.py:get_and_call_function` constructs
    // `Arguments(space, list(args_w))`. One `Vec` at every arity preserves
    // that shape and matches the fast path above:
    // `with_capacity`/`push` lower to `newlist`/`append`.  The fixed
    // `[PY_NULL; N]` leg this replaced ended in `<[T; N]>::index(&array,
    // ..len)` — a RangeTo subslice stays an inherent-impl call where a scalar
    // index would be a place projection — and that call has no registry
    // entry, so this graph and every dunder dispatch reaching one through it
    // dropped to the legacy walker.  `with_capacity` reserves the exact
    // length, so no push reallocates between the shadow-stack reads.
    let mut reloaded = Vec::with_capacity(args_w.len());
    for i in 0..args_w.len() {
        reloaded.push(_roots.get(args_base + i));
    }
    crate::call::call_function_impl_result(w_impl, reloaded.as_slice())
}

/// `isinstance(w_obj, Coroutine) or gen_is_coroutine(w_obj)` from PyPy
/// `generator.py`.  Only a GeneratorIterator may use the
/// `CO_ITERABLE_COROUTINE` marker; native coroutines have their own type.
fn is_coroutine(w_obj: PyObjectRef) -> bool {
    unsafe {
        if pyre_object::generator::is_coroutine(w_obj) {
            return true;
        }
        if !pyre_object::generator::is_generator(w_obj) {
            return false;
        }
        let frame_ptr =
            pyre_object::generator::w_generator_get_frame(w_obj) as *const crate::pyframe::PyFrame;
        // An exhausted generator has a null frame and so no readable flags; an
        // awaited coroutine is never exhausted at this point.
        if frame_ptr.is_null() {
            return false;
        }
        (*frame_ptr)
            .code()
            .flags
            .contains(crate::CodeFlags::ITERABLE_COROUTINE)
    }
}

/// True only for a native `async def` coroutine (`CO_COROUTINE`), excluding
/// `@types.coroutine`-wrapped generators (`CO_ITERABLE_COROUTINE`).  Mirrors
/// `PyCoro_CheckExact`, which gates the GET_AWAITABLE already-awaited guard.
fn is_native_coroutine(w_obj: PyObjectRef) -> bool {
    unsafe { pyre_object::generator::is_coroutine(w_obj) }
}

/// `generator.py get_awaitable_iter` — return the iterator implementing the
/// awaitable protocol for `w_obj`:
///   - `w_obj` itself when it is a coroutine (or `@types.coroutine` generator);
///   - otherwise `w_obj.__await__()`, which must be an iterator.
///
/// `context`: 0 = plain `await`, 1 = `__aenter__`, 2 = `__aexit__` — only the
/// missing-`__await__` error message differs.
pub fn get_awaitable_iter(w_obj: PyObjectRef, context: u32) -> PyResult {
    // `generator.py get_awaitable_iter` keeps `w_obj` live across the
    // `__await__` lookup and call; both can collect.
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_obj);
    let w_obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
    if is_coroutine(w_obj) {
        // GET_AWAITABLE: re-awaiting a native coroutine that is already
        // suspended at an `await` raises (`_PyGen_yf(coro) != NULL`). A native
        // coroutine only ever suspends at an `await`, so "started, not
        // exhausted, not currently running" is exactly that delegating state.
        if is_native_coroutine(w_obj)
            && unsafe {
                pyre_object::generator::w_generator_is_started(w_obj)
                    && !pyre_object::generator::w_generator_is_exhausted(w_obj)
                    && !pyre_object::generator::w_generator_is_running(w_obj)
            }
        {
            return Err(PyError::runtime_error("coroutine is being awaited already"));
        }
        return Ok(w_obj);
    }
    let w_await = crate::typedef::r#type(w_obj)
        .and_then(|w_type| unsafe { lookup_in_type(w_type.as_ptr(), "__await__") });
    let Some(w_await) = w_await else {
        let msg = match context {
            1 => format!(
                "'async with' received an object from __aenter__ that does not \
                 implement __await__: {}",
                object_functionstr_type_name(w_obj),
            ),
            2 => format!(
                "'async with' received an object from __aexit__ that does not \
                 implement __await__: {}",
                object_functionstr_type_name(w_obj),
            ),
            // Python 3.14 changed the plain-await diagnostic from PyPy's
            // historical "object X can't be used ..." spelling.
            _ => format!(
                "'{}' object can't be awaited",
                object_functionstr_type_name(w_obj),
            ),
        };
        return Err(PyError::type_error(msg));
    };
    let w_obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
    let w_type = crate::typedef::r#type(w_obj).map_or(w_obj, |p| p.as_ptr());
    let w_res = unsafe { get_and_call_function(w_await, w_obj, w_type, &[]) }?;
    if is_coroutine(w_res) {
        return Err(PyError::type_error(
            "__await__() returned a coroutine (it must return an iterator \
             instead, see PEP 492)",
        ));
    }
    // `space.lookup(w_res, "__next__")` — w_res must be an iterator.  pyre's
    // generator object (the usual `__await__` return) carries `__next__` at the
    // instance level rather than on its type, so it is accepted directly; other
    // iterators expose `__next__` on their type.
    let has_next = unsafe { pyre_object::generator::is_generator(w_res) }
        || crate::typedef::r#type(w_res)
            .is_some_and(|w_type| unsafe { lookup_in_type(w_type.as_ptr(), "__next__") }.is_some());
    if !has_next {
        return Err(PyError::type_error(format!(
            "__await__() returned non-iterator of type '{}'",
            object_functionstr_type_name(w_res),
        )));
    }
    Ok(w_res)
}

/// _set_names (typeobject.py) — invoke `__set_name__(owner, name)` for one
/// class-body entry.  `__set_name__` is found by a type-only lookup on
/// `type(w_value)` (`space.lookup`, NOT the full attribute protocol, so a
/// user `__getattribute__`/`__getattr__` does not run), then bound and called.
/// A missing `__set_name__` is a no-op.  When the call raises, the original
/// exception is re-raised with an `"Error calling __set_name__ ..."` note
/// attached (PEP 678) by [`add_internal_exception_note`].
///
/// `BaseException_add_note_impl` — `PyObject_GetOptionalAttr` of `__notes__`,
/// an empty list plus `PyObject_SetAttr` when that attribute is missing, then
/// `PyList_Append` on the list that lookup returned.
///
/// `descr_add_note` reads `getdict` with `getitem` / `setitem`, and
/// `_set_names` reaches it through `call_method(..., "add_note")`. A class
/// attribute is invisible to that dict read, a list subclass's `append` runs,
/// and a Python override of `add_note` runs for the internal callers.
/// `_PyException_AddNote` calls this function rather than the method, so the
/// override stays out and the class attribute is the list that grows.
pub(crate) fn base_exception_add_note(exc: PyObjectRef, note: PyObjectRef) -> Result<(), PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let exc_slot = pyre_object::gc_roots::pin_roots(&[exc, note]);
    let note_slot = exc_slot + 1;
    // `getattr_str_impl(..., suppress=true)` is `_PyObject_LookupAttr`: a
    // missing attribute answers null instead of an `AttributeError`. Any
    // other error, including one raised by `__getattribute__`, propagates.
    let lookup = getattr_str_impl(
        pyre_object::gc_roots::shadow_stack_get(exc_slot),
        "__notes__",
        true,
        true,
    );
    let missing = match &lookup {
        Ok(value) => value.is_null(),
        Err(err) => err.kind == crate::PyErrorKind::AttributeError,
    };
    let notes_slot = pyre_object::gc_roots::shadow_stack_len();
    if missing {
        let _ = pyre_object::gc_roots::pin_root(w_list_new(Vec::new()));
        setattr_str(
            pyre_object::gc_roots::shadow_stack_get(exc_slot),
            "__notes__",
            pyre_object::gc_roots::shadow_stack_get(notes_slot),
        )?;
    } else {
        match lookup {
            Ok(existing) => {
                let _ = pyre_object::gc_roots::pin_root(existing);
                if !unsafe {
                    isinstance_list_w(pyre_object::gc_roots::shadow_stack_get(notes_slot))
                } {
                    return Err(PyError::type_error(
                        "Cannot add note: __notes__ is not a list",
                    ));
                }
            }
            Err(err) => return Err(err),
        }
    }
    // Append the list this function holds. A `__setattr__` that stored a
    // different object does not replace it: `PyList_Append` writes the list
    // allocated above, not a second lookup of the attribute.
    unsafe {
        w_list_append(
            pyre_object::gc_roots::shadow_stack_get(notes_slot),
            pyre_object::gc_roots::shadow_stack_get(note_slot),
        );
    }
    Ok(())
}

/// `_PyErr_FormatNote` — attach `text` through [`base_exception_add_note`].
/// The original exception is re-raised with the note on it. When attaching
/// fails, `_PyErr_ChainExceptions1` chains that original as `__context__` of
/// the failure.
pub(crate) fn add_internal_exception_note(error: &mut PyError, text: &str) -> Result<(), PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let exc = error.to_exc_object();
    let exc_slot = pyre_object::gc_roots::pin_roots(&[exc]);
    let note = w_str_new_managed(text);
    let note_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(note);
    match base_exception_add_note(
        pyre_object::gc_roots::shadow_stack_get(exc_slot),
        pyre_object::gc_roots::shadow_stack_get(note_slot),
    ) {
        Ok(()) => {
            error.set_exc_object(pyre_object::gc_roots::shadow_stack_get(exc_slot));
            Ok(())
        }
        Err(mut note_error) => {
            let note_exc = note_error.to_exc_object();
            let note_exc_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(note_exc);
            crate::error::chain_context(
                pyre_object::gc_roots::shadow_stack_get(note_exc_slot),
                pyre_object::gc_roots::shadow_stack_get(exc_slot),
            );
            note_error.set_exc_object(pyre_object::gc_roots::shadow_stack_get(note_exc_slot));
            Err(note_error)
        }
    }
}

pub(crate) unsafe fn set_name(
    w_owner: PyObjectRef,
    w_name: PyObjectRef,
    w_value: PyObjectRef,
) -> Result<(), PyError> {
    // typeobject.py `_set_names` — `space.lookup(w_value, '__set_name__')`
    // then `space.get_and_call_function(w_meth, w_value, w_type, key)`.
    // The lookup intern-boxes the name when jitted and may collect; pin the
    // owner, name, value, and value-type before it (`gc_push_roots`) and
    // restore them for the call (`gc_restore_root`).
    let w_valtype = match crate::typedef::r#type(w_value) {
        Some(t) => t,
        None => return Ok(()),
    };
    let _roots = pyre_object::gc_roots::push_roots();
    let owner_slot =
        pyre_object::gc_roots::pin_roots(&[w_owner, w_name, w_value, w_valtype.as_ptr()]);
    let name_slot = owner_slot + 1;
    let value_slot = owner_slot + 2;
    let valtype_slot = owner_slot + 3;
    let set_name_meth = match unsafe {
        lookup_in_type_where(
            pyre_object::gc_roots::shadow_stack_get(valtype_slot),
            "__set_name__",
        )
    } {
        Some(m) => m,
        None => return Ok(()),
    };
    // `space.get_and_call_function(w_meth, w_value, w_type, key)` — `w_value`
    // is the descriptor instance (bound as the receiver), and the call args
    // are `(owner, name)`: `__set_name__(self, owner, name)`.
    //
    // The hook is arbitrary Python, so the operands cannot stay in Rust
    // locals across it: the failure arm below names the descriptor, its type
    // and the owner, and reading any of them from a pre-call address would
    // build the note out of reclaimed memory.
    let meth_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(set_name_meth);
    match unsafe {
        get_and_call_function(
            pyre_object::gc_roots::shadow_stack_get(meth_slot),
            pyre_object::gc_roots::shadow_stack_get(value_slot),
            pyre_object::gc_roots::shadow_stack_get(valtype_slot),
            &[
                pyre_object::gc_roots::shadow_stack_get(owner_slot),
                pyre_object::gc_roots::shadow_stack_get(name_slot),
            ],
        )
    } {
        Ok(_) => Ok(()),
        Err(e) => {
            let _note_roots = pyre_object::gc_roots::push_roots();
            let mut e = e;
            let err_slot = e.pin(&_note_roots);
            let w_name = pyre_object::gc_roots::shadow_stack_get(name_slot);
            // `%R` on the key: a namespace entry stored under a non-string
            // key is named in the note by its own repr.
            let name_repr = if unsafe { is_str(w_name) } {
                crate::display::format_wtf8_repr(unsafe { w_str_get_wtf8(w_name) })
            } else {
                unsafe { crate::display::py_repr_wtf8(w_name) }
                    .ok()
                    .and_then(|repr| repr.as_str().ok().map(str::to_owned))
                    .unwrap_or_default()
            };
            // `typeobject.py _set_names` still names `w_value` and `w_type`
            // after `space.repr`. Reload both from the pin; repr may collect.
            let w_value = pyre_object::gc_roots::shadow_stack_get(value_slot);
            let w_owner = pyre_object::gc_roots::shadow_stack_get(owner_slot);
            let val_type_name = match crate::typedef::r#type(w_value) {
                Some(t) => unsafe { pyre_object::w_type_get_name(t.as_ptr()) }.to_string(),
                None => String::new(),
            };
            let owner_name = unsafe { pyre_object::w_type_get_name(w_owner) }.to_string();
            e.reload(&_note_roots, err_slot);
            add_internal_exception_note(
                &mut e,
                &format!(
                    "Error calling __set_name__ on '{val_type_name}' instance {name_repr} in '{owner_name}'"
                ),
            )?;
            Err(e)
        }
    }
}

#[majit_macros::dont_look_inside]
pub(crate) fn dict_missing_or_key_error(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    // dictmultiobject.py `W_DictMultiObject.descr_getitem` — after
    // `self.getitem(w_key)` misses, `space.lookup(self, '__missing__')` then
    // `space.get_and_call_function(w_missing, self, w_key)`.  RPython's
    // shadowstack (`gc_push_roots` / `gc_restore_root`) keeps `self` and
    // `w_key` live across that lookup; reload both and the type from slots
    // here after `lookup_in_type` (it intern-boxes the name when jitted).
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, index]);
    let index_slot = obj_slot + 1;
    let obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
    if let Some(w_type_obj) = crate::typedef::r#type(obj) {
        let type_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_type_obj.as_ptr());
        let dict_type = crate::typedef::gettypeobject(&pyre_object::DICT_TYPE);
        let w_type_obj = pyre_object::gc_roots::shadow_stack_get(type_slot);
        if !dict_type.is_null()
            && !std::ptr::eq(w_type_obj, dict_type)
            && let Some(w_missing) = unsafe { lookup_in_type(w_type_obj, "__missing__") }
        {
            // dictmultiobject.py:166 space.get_and_call_function(
            //     w_missing, self, w_key)
            return unsafe {
                get_and_call_function(
                    w_missing,
                    pyre_object::gc_roots::shadow_stack_get(obj_slot),
                    pyre_object::gc_roots::shadow_stack_get(type_slot),
                    &[pyre_object::gc_roots::shadow_stack_get(index_slot)],
                )
            };
        }
    }
    Err(PyError::key_error_with_key(
        pyre_object::gc_roots::shadow_stack_get(index_slot),
    ))
}

/// Get item by index: `obj[index]`.
///
/// Dispatches based on the type of `obj`.

pub fn getitem(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    // `pypy/objspace/std/dictproxyobject.py descr_getitem` →
    // `space.getitem(self.w_mapping, w_key)` — forward through the
    // proxy to its wrapped mapping.  The unwrap happens at the
    // entrance so all downstream dict arms (and dict-subclass
    // overrides via the wrapped W_DictObject) see the underlying
    // mapping unchanged.
    unsafe {
        let obj = if pyre_object::is_dict_proxy(obj) {
            pyre_object::w_dict_proxy_get_mapping(obj)
        } else {
            obj
        };
        // A builtin sequence subclass (`is_list`/`is_tuple`/… stays true on
        // the retagged layout) overriding `__getitem__` must dispatch the
        // override; the by-layout slot below gives the inherited builtin
        // subscript for exact instances and non-overriding subclasses.
        if (is_list(obj)
            || is_tuple(obj)
            || is_str(obj)
            || pyre_object::bytesobject::is_bytes_like(obj)
            || pyre_object::is_w_range(obj))
            && let Some((method, w_type)) = subclass_special_override(obj, "__getitem__")
        {
            return get_and_call_function(method, obj, w_type, &[index]);
        }
        getitem_slot(obj, index)
    }
}

/// The builtin `__getitem__` slot body: subscript dispatch by concrete
/// layout.  Reached from the operator [`getitem`] for exact instances and
/// non-overriding subclasses, and bound directly as the `list`/`str`/`tuple`
/// `__getitem__` slot so a subclass override's `super().__getitem__` resolves
/// to the inherited builtin subscript instead of re-entering override
/// dispatch (which would recurse).
pub(crate) fn getitem_slot(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    unsafe {
        if is_list(obj) {
            return getitem_list(obj, index);
        }
        if is_tuple(obj) {
            return getitem_tuple(obj, index);
        }
        if is_dict(obj) {
            // `pypy/objspace/std/dictmultiobject.py W_DictMultiObject
            // .descr_getitem` → `self.getitem(w_key)` then, on miss,
            // `space.lookup(self, '__missing__')`.  `w_dict_lookup_checked`
            // runs the key's `__hash__`/`__eq__` and may collect; the dict
            // and key are raw locals.  Pin them and reload after the probe
            // (`gc_restore_root`) before `type(self)` / `__missing__`.
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, index]);
            let index_slot = obj_slot + 1;
            return match pyre_object::dictmultiobject::w_dict_lookup_checked(
                pyre_object::gc_roots::shadow_stack_get(obj_slot),
                pyre_object::gc_roots::shadow_stack_get(index_slot),
            ) {
                Ok(Some(val)) => Ok(val),
                Ok(None) => {
                    // dictmultiobject.py:166-170 — dict subclass
                    // __missing__ dispatch before KeyError
                    dict_missing_or_key_error(
                        pyre_object::gc_roots::shadow_stack_get(obj_slot),
                        pyre_object::gc_roots::shadow_stack_get(index_slot),
                    )
                }
                Err(_) => Err(take_pending_dict_key_error(
                    pyre_object::gc_roots::shadow_stack_get(index_slot),
                )),
            };
        }
        if is_str(obj) {
            return getitem_str(obj, index);
        }
        if pyre_object::bytesobject::is_bytes_like(obj) {
            return getitem_bytes_like(obj, index);
        }
        if is_type(obj) {
            return getitem_type(obj, index);
        }
        if is_instance(obj) {
            return getitem_instance(obj, index);
        }
        if pyre_object::is_w_range(obj) {
            return getitem_range(obj, index);
        }
        // descroperation.py DescrOperation.getitem — any object
        // whose type defines `__getitem__` on its MRO is subscriptable
        // (the arms above are fast paths for builtin sequence/mapping
        // types).  Covers W_Root types like `re.Match` whose typedef
        // registers `__getitem__`.  The lookup may collect; pin the
        // receiver, key, and type and reload them for the call.
        let _roots = pyre_object::gc_roots::push_roots();
        let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, index]);
        let index_slot = obj_slot + 1;
        if let Some(w_type) =
            crate::typedef::r#type(pyre_object::gc_roots::shadow_stack_get(obj_slot))
        {
            let type_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(w_type.as_ptr());
            if let Some(method) = lookup_in_type_where(
                pyre_object::gc_roots::shadow_stack_get(type_slot),
                "__getitem__",
            ) {
                return get_and_call_function(
                    method,
                    pyre_object::gc_roots::shadow_stack_get(obj_slot),
                    pyre_object::gc_roots::shadow_stack_get(type_slot),
                    &[pyre_object::gc_roots::shadow_stack_get(index_slot)],
                );
            }
        }
        Err(PyError::type_error(format!(
            "'{}' object is not subscriptable",
            crate::error::type_name_of(pyre_object::gc_roots::shadow_stack_get(obj_slot)),
        )))
    }
}

/// `pypy/interpreter/baseobjspace.py getindex_w` — the `TypeError`
/// raised when a sequence subscript is neither an integer nor a slice:
/// `"<descr> indices must be integers or slices, not <type>"` (the `%T`
/// operand names the key's own class).  The reference `pypy3` quotes the type
/// name here; 3.14 emits it unquoted, and only the `str` wording
/// ([`string_index_type_error`]) keeps the quotes.
///
/// `getindex_w` also catches a `TypeError` raised *while* coercing the key
/// through `__index__` and rewrites it to this message.  3.14 does not: a key
/// that has an `__index__` at all surfaces whatever that `__index__` raised
/// ("__index__ returned non-int (type float)"), and this wording is reserved
/// for a key with no `__index__` to try.  Every subscript path therefore
/// tests for the slot up front and lets `space_index`'s error propagate.
fn index_type_error(descr: &str, index: PyObjectRef) -> PyError {
    let tp = if index.is_null() {
        "NULL".to_string()
    } else {
        object_functionstr_type_name(index)
    };
    PyError::type_error(format!(
        "{descr} indices must be integers or slices, not {tp}"
    ))
}

/// Python 3.14 string-subscript wording.  Unlike this PyPy source's generic
/// `getindex_w(..., "string")` remap, 3.14 omits "or slices" after the slice
/// case has already been handled, and keeps the type name quoted.
fn string_index_type_error(index: PyObjectRef) -> PyError {
    let tp = if index.is_null() {
        "NULL".to_string()
    } else {
        object_functionstr_type_name(index)
    };
    PyError::type_error(format!("string indices must be integers, not '{tp}'"))
}

#[inline(never)]
unsafe fn getitem_list(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    let mut obj = obj;
    let mut index = index;
    if is_slice(index) {
        let (rs, rp, st) = {
            // Every slice component goes through `__index__`, so this runs
            // Python and a minor collection can move the list underneath.
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::pin_roots(&[obj]);
            let unpacked = crate::sliceobject::slice_unpack(
                w_slice_get_start(index),
                w_slice_get_stop(index),
                w_slice_get_step(index),
            )?;
            obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
            unpacked
        };
        // The length is read after the unpack, not before: a component's
        // `__index__` may have appended to or truncated this very list, and
        // the bounds are clamped against what it holds now.
        let len = w_list_len(obj) as i64;
        let (start, stop, step, slicelength) =
            crate::sliceobject::slice_adjust_indices(rs, rp, st, len);
        // `W_ListObject.descr_getitem`: an empty slice is `make_empty_list`
        // before `getslice`. The length is already the post-`__index__` value.
        if slicelength == 0 {
            return Ok(w_list_new(Vec::new()));
        }
        // `W_ListObject.getslice` → `strategy.getslice`. Range strategies
        // materialise inside that call (`BaseRangeListStrategy.getslice`).
        return Ok(pyre_object::listobject::w_list_getslice(
            obj,
            start,
            stop,
            step,
            slicelength,
        ));
    }
    // `descr_getitem`: getindex_w(index, IndexError, "list") coerces a
    // non-slice key through `__index__`.  The coercion is inlined rather
    // than routed through the `Result<i64>` `subscript_index_w` helper,
    // whose payload fails to bind a concrete Int repr in the rtyper
    // (concretetype None → the codewriter mis-colors it Ref), so the hot
    // integer subscript keeps its Int repr concrete.
    let idx = if is_int(index) {
        w_int_get_value(index)
    } else if pyre_object::pyobject::is_int_or_long(index) || lookup(index, "__index__").is_some() {
        let indexed = {
            // `__index__` is user code: `BINARY_SUBSCR` pops the receiver
            // before dispatching here, so nothing else roots it across the
            // call. A list is nursery-allocated, so read the address back —
            // a minor collection during the call moves it.
            // The index is read back for the overflow message's type name.
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, index]);
            let indexed = space_index(index)?;
            obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
            index = pyre_object::gc_roots::shadow_stack_get(obj_slot + 1);
            indexed
        };
        if is_int(indexed) {
            w_int_get_value(indexed)
        } else {
            match i64::try_from(w_long_get_value(indexed)) {
                Ok(i) => i,
                // `getindex_w` overflow reports the source type, not the coerced int.
                Err(_) => {
                    return Err(PyError::new(
                        PyErrorKind::IndexError,
                        format!(
                            "cannot fit '{}' into an index-sized integer",
                            object_functionstr_type_name(index)
                        ),
                    ));
                }
            }
        }
    } else {
        return Err(index_type_error("list", index));
    };
    // `listobject.py` `W_ListObject.descr_getitem` calls `self.getitem(index)`
    // with no list lock. `w_list_getitem` is opaque (`dont_look_inside` pairs
    // acquire/release), so the `gil_ready == 0` arm's look-inside call is
    // what `grab_initial_jitcodes` uses to reach `w_list_getitem_inner`.
    // Publication fails the guard and the retrace takes the locked wrapper.
    // The BINARY_SUBSCR walker descends that inner body by name
    // (`list_getitem_jitcode`).
    let ready = pyre_object::gil_ready::gil_ready_word();
    let item = if ready != 0 {
        w_list_getitem(obj, idx)
    } else {
        pyre_object::w_list_getitem_inner(obj, idx)
    };
    match item {
        Some(val) => Ok(val),
        None => Err(PyError::index_error("list index out of range")),
    }
}

/// Step-1 `ll_listslice_startstop` wrap for `BINARY_SLICE` on a tuple.
/// Bounds are already normalised machine indices; `eval_slice_index` must
/// not run inside this leaf.
///
/// Empty is a fresh empty array. Otherwise [`tuple_getslice_step1_block`]
/// (`ll_newlist` plus `ll_arraycopy` for an array tuple).
#[inline(never)]
pub(crate) unsafe fn tuple_slice_startstop(
    obj: PyObjectRef,
    start: usize,
    stop: usize,
) -> PyObjectRef {
    let _roots = pyre_object::gc_roots::push_roots();
    let obj = pyre_object::gc_roots::pin_root(obj);
    let slicelength = stop.saturating_sub(start) as i64;
    let block = if slicelength == 0 {
        tuple_ll_newlist(0)
    } else {
        tuple_getslice_step1_block(obj, start as i64, slicelength)
    };
    pyre_object::tupleobject::wraptuple(block)
}

/// `tupleobject.py descr_getitem` → `_getslice`.
///
/// `slice_unpack` then `slice_adjust_indices`. An empty slice is a fresh
/// empty array. Step 1 is `ll_newlist` plus `ll_arraycopy`. Any other step
/// is `_getslice_advanced` (a plain loop, no hint). `wraptuple` builds the
/// tuple: length 2 is `wraptuple2`, every other length adopts the array.
#[inline(never)]
unsafe fn tuple_descr_getslice(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    let len = w_tuple_len(obj) as i64;
    // One bracket for `obj` across `slice_unpack`. `__index__` can collect,
    // and a tuple is nursery-allocated. The parameter stays the pin value;
    // the reloaded word is a new local.
    let (obj_now, rs, rp, st) = {
        let _roots = pyre_object::gc_roots::push_roots();
        let obj_slot = pyre_object::gc_roots::pin_roots(&[obj]);
        let unpacked = crate::sliceobject::slice_unpack(
            w_slice_get_start(index),
            w_slice_get_stop(index),
            w_slice_get_step(index),
        )?;
        let obj_now = pyre_object::gc_roots::shadow_stack_get(obj_slot);
        (obj_now, unpacked.0, unpacked.1, unpacked.2)
    };
    let (start, _stop, step, slicelength) =
        crate::sliceobject::slice_adjust_indices(rs, rp, st, len);
    let block = if slicelength == 0 {
        tuple_ll_newlist(0)
    } else if step == 1 {
        tuple_getslice_step1_block(obj_now, start, slicelength)
    } else {
        tuple_getslice_advanced_block(obj_now, start, step, slicelength)
    };
    Ok(pyre_object::tupleobject::wraptuple(block))
}

/// `W_TupleObject` and a tuple user subclass store `wrappeditems`. A
/// specialised pair does not.
#[inline(never)]
unsafe fn tuple_has_wrappeditems(obj: PyObjectRef) -> bool {
    let ob_type = (*obj).ob_type;
    std::ptr::eq(ob_type, &pyre_object::TUPLE_TYPE)
        || std::ptr::eq(ob_type, &pyre_object::TUPLE_USER_TYPE)
}

/// `rlist.py ll_newlist` for a fixed list (`_ll_fixed_alloc_and_clear`,
/// `@jit.oopspec("newlist_clear(count)")`). A traced call is
/// `new_array_clear`; the body is the interpreter's allocation. No root
/// bracket. The fill loop stays in this body so the step-1 caller has none.
#[inline(never)]
#[majit_macros::oopspec("newlist_clear(count)")]
unsafe fn tuple_ll_newlist(count: i64) -> *mut pyre_object::object_array::ItemsBlock {
    // `count` is Signed (`_ll_alloc_and_clear`). The usize conversion lives
    // in this oopspec body so a traced call keeps the Signed length and
    // `new_array_clear` sees a constant item count.
    let count = count as usize;
    if let Some(block) = pyre_object::object_array::alloc_cleared_ref_items_block_gc(count) {
        return block;
    }
    pyre_object::object_array::alloc_tuple_items_block(&vec![pyre_object::PY_NULL; count])
}

/// Step 1. An array tuple is `ll_listslice_startstop`. A specialised pair
/// boxes through `w_tuple_getitem`, which allocates, so that copy is its
/// own body.
#[inline(never)]
unsafe fn tuple_getslice_step1_block(
    obj: PyObjectRef,
    start: i64,
    slicelength: i64,
) -> *mut pyre_object::object_array::ItemsBlock {
    if tuple_has_wrappeditems(obj) {
        tuple_ll_listslice_startstop(obj, start, slicelength)
    } else {
        tuple_copy_boxed_items(obj, start, 1, slicelength)
    }
}

/// `rlist.py ll_listslice_startstop`: `ll_newlist` plus `ll_arraycopy`.
///
/// `wrappeditems` is a raw items-block pointer, not a Rust slice of the GC
/// array, so the copy is `jit_ll_arraycopy` into the fresh block.
#[inline(never)]
unsafe fn tuple_ll_listslice_startstop(
    obj: PyObjectRef,
    start: i64,
    slicelength: i64,
) -> *mut pyre_object::object_array::ItemsBlock {
    let n = slicelength as usize;
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::pin_roots(&[obj]);
    let dest = tuple_ll_newlist(slicelength);
    // The pin operand has to be its own local. A cast in the call is not one.
    let dest_ref = dest as PyObjectRef;
    let dest_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(dest_ref);
    let obj_now = pyre_object::gc_roots::shadow_stack_get(obj_slot);
    if n > 0 {
        let src = (*(obj_now as *const pyre_object::tupleobject::W_TupleObject)).wrappeditems;
        let dest_now = pyre_object::gc_roots::shadow_stack_get(dest_slot);
        pyre_object::object_array::jit_ll_arraycopy(
            src as PyObjectRef,
            dest_now,
            start,
            0,
            slicelength,
        );
    }
    pyre_object::gc_roots::shadow_stack_get(dest_slot) as *mut pyre_object::object_array::ItemsBlock
}

/// `tupleobject.py _getslice_advanced`. No JIT hint. The loop stays in the
/// callee so a step-1 trace of [`tuple_descr_getslice`] does not contain it.
#[inline(never)]
unsafe fn tuple_getslice_advanced_block(
    obj: PyObjectRef,
    start: i64,
    step: i64,
    slicelength: i64,
) -> *mut pyre_object::object_array::ItemsBlock {
    if tuple_has_wrappeditems(obj) {
        tuple_getslice_advanced_array(obj, start, step, slicelength)
    } else {
        tuple_copy_boxed_items(obj, start, step, slicelength)
    }
}

/// `_getslice_advanced` for an array tuple: allocate under one pin of `obj`,
/// then a plain store loop. `w_tuple_getitem` of an array only reads the
/// item word, so the loop does not pin per item.
#[inline(never)]
unsafe fn tuple_getslice_advanced_array(
    obj: PyObjectRef,
    start: i64,
    step: i64,
    slicelength: i64,
) -> *mut pyre_object::object_array::ItemsBlock {
    let n = slicelength as usize;
    let (src_base, block) = {
        let _roots = pyre_object::gc_roots::push_roots();
        let obj_slot = pyre_object::gc_roots::pin_roots(&[obj]);
        let block = tuple_ll_newlist(slicelength);
        let obj_now = pyre_object::gc_roots::shadow_stack_get(obj_slot);
        let src = (*(obj_now as *const pyre_object::tupleobject::W_TupleObject)).wrappeditems;
        (
            pyre_object::object_array::items_block_items_base(src),
            block,
        )
    };
    let mut index = start;
    for i in 0..n {
        let item = *src_base.add(index as usize);
        pyre_object::object_array::items_block_set_ref(block, i, item);
        if i + 1 < n {
            index += step;
        }
    }
    block
}

/// `_getslice_advanced` for a specialised pair. `w_tuple_getitem` boxes, so
/// reload the tuple after each box. The pin loop is not on the traced
/// array-tuple arm.
#[inline(never)]
unsafe fn tuple_copy_boxed_items(
    obj: PyObjectRef,
    start: i64,
    step: i64,
    slicelength: i64,
) -> *mut pyre_object::object_array::ItemsBlock {
    let n = slicelength as usize;
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::pin_roots(&[obj]);
    let block = tuple_ll_newlist(slicelength);
    let block_ref = block as PyObjectRef;
    let block_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(block_ref);
    let mut index = start;
    for i in 0..n {
        let item = w_tuple_getitem(pyre_object::gc_roots::shadow_stack_get(obj_slot), index)
            .unwrap_or(pyre_object::PY_NULL);
        let item_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(item);
        pyre_object::object_array::items_block_set_ref(
            pyre_object::gc_roots::shadow_stack_get(block_slot)
                as *mut pyre_object::object_array::ItemsBlock,
            i,
            pyre_object::gc_roots::shadow_stack_get(item_slot),
        );
        if i + 1 < n {
            index += step;
        }
    }
    pyre_object::gc_roots::shadow_stack_get(block_slot)
        as *mut pyre_object::object_array::ItemsBlock
}

#[inline(never)]
unsafe fn getitem_tuple(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    let mut obj = obj;
    let mut index = index;
    if is_slice(index) {
        // `tupleobject.py descr_getitem` → `_getslice`.
        return tuple_descr_getslice(obj, index);
    }
    // `descr_getitem`: getindex_w(index, IndexError, "tuple") — coercion
    // inlined for the same rtyper reason as `getitem_list`.
    let idx = if is_int(index) {
        w_int_get_value(index)
    } else if pyre_object::pyobject::is_int_or_long(index) || lookup(index, "__index__").is_some() {
        let indexed = {
            // `__index__` is user code: `BINARY_SUBSCR` pops the receiver
            // before dispatching here, so nothing else roots it across the
            // call. A tuple is nursery-allocated, so read the address back —
            // a minor collection during the call moves it.
            // The index is read back for the overflow message's type name.
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, index]);
            let indexed = space_index(index)?;
            obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
            index = pyre_object::gc_roots::shadow_stack_get(obj_slot + 1);
            indexed
        };
        if is_int(indexed) {
            w_int_get_value(indexed)
        } else {
            match i64::try_from(w_long_get_value(indexed)) {
                Ok(i) => i,
                Err(_) => {
                    return Err(PyError::new(
                        PyErrorKind::IndexError,
                        format!(
                            "cannot fit '{}' into an index-sized integer",
                            object_functionstr_type_name(index)
                        ),
                    ));
                }
            }
        }
    } else {
        return Err(index_type_error("tuple", index));
    };
    match w_tuple_getitem(obj, idx) {
        Some(val) => Ok(val),
        None => Err(PyError::index_error("tuple index out of range")),
    }
}

#[inline(never)]
unsafe fn getitem_str(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    // Index code points through the surrogate-aware WTF-8 view so a
    // surrogateescape / surrogatepass-decoded string can be sliced and
    // indexed without going through `w_str_get_value`.
    //
    // `_index_to_byte` (`unicodeobject.py`) reads an ASCII payload's byte
    // at the code point index; a wide or surrogate-bearing one resolves the
    // position through the string's cached `rutf8` index table, so a read is
    // O(1) either way and nothing here has to materialise the code points.
    let mut obj = obj;
    let mut index = index;
    let len = w_str_len(obj);
    if is_slice(index) {
        // `pypy/objspace/std/unicodeobject.py W_UnicodeObject._getitem_slice`
        // → `slice.indices(len)` (`pypy/objspace/std/sliceobject.py`).
        // Use the shared adjusted slice count so very large steps do not
        // overflow the index loop.
        let (rs, rp, st) = {
            // `slice_unpack` runs each component's `__index__`, so this runs
            // Python.  `space.str` answers a nursery header, so read the
            // address back: a minor collection during the call moves it.  The
            // length is read before, as `slice.indices` takes it — a string
            // cannot be resized.
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::pin_roots(&[obj]);
            let unpacked = crate::sliceobject::slice_unpack(
                w_slice_get_start(index),
                w_slice_get_stop(index),
                w_slice_get_step(index),
            )?;
            obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
            unpacked
        };
        let (start, _stop, step, slicelength) =
            crate::sliceobject::slice_adjust_indices(rs, rp, st, len as i64);
        // `_unicode_sliced` (unicodeobject.py) cuts the utf8
        // storage, and `ll_stringslice_startstop` (rstr.py) hands the
        // source string back unchanged for `start == 0 and stop >= len` — so a
        // whole-string slice shares its operand's storage and `is_w`
        // (unicodeobject.py:110-111) reports the two identical.  Only for an
        // exact `str`: a subclass slices to a fresh base `str`, and `is_w`
        // rejects a `user_overridden_class` operand anyway
        // (unicodeobject.py:106).
        if step == 1
            && start == 0
            && slicelength == len as i64
            && pyre_object::pyobject::is_exact_type(obj, &pyre_object::pyobject::STR_TYPE)
        {
            return Ok(obj);
        }
        return Ok(pyre_object::unicodeobject::w_str_slice_codepoints(
            obj,
            start,
            step,
            slicelength,
        ));
    }
    // `descr_getitem`: getindex_w(index, IndexError, "string") — coercion
    // inlined for the same rtyper reason as `getitem_list`.
    let idx = if is_int(index) {
        w_int_get_value(index)
    } else if pyre_object::pyobject::is_int_or_long(index) || lookup(index, "__index__").is_some() {
        let indexed = {
            // `__index__` is user code: `BINARY_SUBSCR` pops the receiver
            // before dispatching here, so nothing else roots it across the
            // call. `space.str` answers a nursery header, so read the address
            // back — a minor collection during the call moves it.
            // The index is read back for the overflow message's type name.
            let _roots = pyre_object::gc_roots::push_roots();
            let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, index]);
            let indexed = space_index(index)?;
            obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
            index = pyre_object::gc_roots::shadow_stack_get(obj_slot + 1);
            indexed
        };
        if is_int(indexed) {
            w_int_get_value(indexed)
        } else {
            match i64::try_from(w_long_get_value(indexed)) {
                Ok(i) => i,
                Err(_) => {
                    return Err(PyError::new(
                        PyErrorKind::IndexError,
                        format!(
                            "cannot fit '{}' into an index-sized integer",
                            object_functionstr_type_name(index)
                        ),
                    ));
                }
            }
        }
    } else {
        return Err(string_index_type_error(index));
    };
    // `_getitem_result` (`unicodeobject.py`) after `getindex_w`.
    match unsafe { pyre_object::unicodeobject::w_str_getitem(obj, idx) } {
        Some(item) => Ok(item),
        None => Err(PyError::index_error("string index out of range")),
    }
}

#[inline(never)]
unsafe fn getitem_bytes_like(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    let _obj_roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(obj);
    let index_slot = pyre_object::gc_roots::shadow_stack_len();
    let index = pyre_object::gc_roots::pin_root(index);
    let obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
    let is_bytes = pyre_object::bytesobject::is_bytes(obj);
    if is_slice(index) {
        // stringmethods.py / bytearrayobject.py `descr_getitem`: unpack the
        // slice before reading the sequence length (an `__index__` method may
        // mutate a bytearray), then use `adjust_indices`' explicit slice
        // length.  Iterating by that count also avoids overflowing on the
        // final `start + step` for a step near `sys.maxsize`.
        let (rs, rp, st) = crate::sliceobject::slice_unpack(
            w_slice_get_start(index),
            w_slice_get_stop(index),
            w_slice_get_step(index),
        )?;
        let obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
        let len = pyre_object::bytesobject::bytes_like_len(obj) as i64;
        let (start, _stop, step, slicelength) =
            crate::sliceobject::slice_adjust_indices(rs, rp, st, len);
        // `_new(self._value[start:stop])` (stringmethods.py descr_getslice)
        // runs through `ll_stringslice_startstop` (rstr.py), which
        // hands the source string back unchanged for `start == 0 and
        // stop >= len`; `is_w` (bytesobject.py) then reports the whole
        // slice identical to its operand.  Immutable exact `bytes` only — a
        // `bytearray` gets a fresh object from `_new` because it is mutable,
        // and a subclass keeps pointer identity through `is_w`.
        if step == 1
            && start == 0
            && slicelength == len
            && is_bytes
            && pyre_object::pyobject::is_exact_type(obj, &pyre_object::bytesobject::BYTES_TYPE)
        {
            return Ok(obj);
        }
        let mut result = Vec::new();
        let mut i = start;
        for n in 0..slicelength {
            result.push(pyre_object::bytesobject::bytes_like_getitem(
                obj, i as usize,
            ));
            if n + 1 < slicelength {
                i += step;
            }
        }
        return Ok(if is_bytes {
            pyre_object::bytesobject::w_bytes_from_bytes(&result)
        } else {
            pyre_object::bytearrayobject::w_bytearray_from_bytes(&result)
        });
    }
    // `descr_getitem`: getindex_w(index, IndexError, "byte") — coercion
    // inlined for the same rtyper reason as `getitem_list`.
    let mut obj = obj;
    let idx = if is_int(index) {
        w_int_get_value(index)
    } else if pyre_object::pyobject::is_int_or_long(index) || lookup(index, "__index__").is_some() {
        let indexed = space_index(index)?;
        obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
        let index = pyre_object::gc_roots::shadow_stack_get(index_slot);
        if is_int(indexed) {
            w_int_get_value(indexed)
        } else {
            match i64::try_from(w_long_get_value(indexed)) {
                Ok(i) => i,
                Err(_) => {
                    return Err(PyError::new(
                        PyErrorKind::IndexError,
                        format!(
                            "cannot fit '{}' into an index-sized integer",
                            object_functionstr_type_name(index)
                        ),
                    ));
                }
            }
        }
    } else {
        let descr = if is_bytes { "byte" } else { "bytearray" };
        return Err(index_type_error(descr, index));
    };
    let len = pyre_object::bytesobject::bytes_like_len(obj) as i64;
    let actual = if idx < 0 { len + idx } else { idx };
    if actual >= 0 && actual < len {
        return Ok(w_int_new(
            pyre_object::bytesobject::bytes_like_getitem(obj, actual as usize) as i64,
        ));
    }
    // `bytes_item` names no type in the out-of-range message, unlike
    // `bytearray_getitem`.
    if is_bytes {
        Err(PyError::index_error("index out of range"))
    } else {
        Err(PyError::index_error("bytearray index out of range"))
    }
}

#[inline(never)]
unsafe fn getitem_type(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    // descroperation.py `DescrOperation.getitem` — `space.lookup(w_obj,
    // '__getitem__')` then, for a type, `space.getattr(w_obj,
    // '__class_getitem__')`.  Each lookup may collect; pin the class and
    // key (`gc_push_roots`) and reload them after (`gc_restore_root`).
    let _roots = pyre_object::gc_roots::push_roots();
    let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, index]);
    let index_slot = obj_slot + 1;
    // A metaclass `__getitem__` (resolved on `type(cls)`'s MRO, e.g.
    // `EnumMeta.__getitem__`) applies before the PEP 560
    // `__class_getitem__` fallback: `Color['RED']` is `type(Color)
    // .__getitem__(Color, 'RED')`.  `type` itself defines no `__getitem__`,
    // so an ordinary class still takes the `__class_getitem__` path below.
    if let Some(w_meta) = crate::typedef::r#type(pyre_object::gc_roots::shadow_stack_get(obj_slot))
    {
        let meta_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_meta.as_ptr());
        if let Some(method) = lookup_in_type_where(
            pyre_object::gc_roots::shadow_stack_get(meta_slot),
            "__getitem__",
        ) {
            return get_and_call_function(
                method,
                pyre_object::gc_roots::shadow_stack_get(obj_slot),
                pyre_object::gc_roots::shadow_stack_get(meta_slot),
                &[pyre_object::gc_roots::shadow_stack_get(index_slot)],
            );
        }
    }
    let obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
    let index = pyre_object::gc_roots::shadow_stack_get(index_slot);
    // descroperation.py:362 — `type[X]` (the operand is exactly `type`) builds
    // a GenericAlias even though `type` defines no `__class_getitem__`.
    if std::ptr::eq(obj, crate::typedef::w_type()) {
        return crate::_pypy_generic_alias::generic_alias_class_getitem(&[obj, index]);
    }
    // Python 3.9+ generic subscript: cls[X] → cls.__class_getitem__(X)
    // (`descroperation.py` getattr lookup).
    if let Some(method) = lookup_in_type_where(obj, "__class_getitem__") {
        // PyPy's generic lookup treats an explicit None as disabling the
        // inherited subscription hook.  Other non-callable values still
        // reach the call and raise their ordinary not-callable TypeError.
        let obj = pyre_object::gc_roots::shadow_stack_get(obj_slot);
        let index = pyre_object::gc_roots::shadow_stack_get(index_slot);
        if !pyre_object::is_none(method) {
            return get_and_call_function(method, obj, obj, &[index]);
        }
    }
    // abstract.py descr_getitem — a class that defines neither a metaclass
    // __getitem__ nor __class_getitem__ is not subscriptable.
    Err(PyError::type_error(format!(
        "type '{}' is not subscriptable",
        w_type_get_name(pyre_object::gc_roots::shadow_stack_get(obj_slot)),
    )))
}

#[inline(never)]
unsafe fn getitem_instance(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    // descroperation.py `DescrOperation.getitem` — `space.lookup(w_obj,
    // '__getitem__')`.  The lookup may collect; pin the instance, key, and
    // class and reload them for the call.
    let _roots = pyre_object::gc_roots::push_roots();
    let w_type = w_instance_get_type(obj);
    let obj_slot = pyre_object::gc_roots::pin_roots(&[obj, index, w_type]);
    let index_slot = obj_slot + 1;
    let type_slot = obj_slot + 2;
    if let Some(method) = lookup_in_type_where(
        pyre_object::gc_roots::shadow_stack_get(type_slot),
        "__getitem__",
    ) {
        return get_and_call_function(
            method,
            pyre_object::gc_roots::shadow_stack_get(obj_slot),
            pyre_object::gc_roots::shadow_stack_get(type_slot),
            &[pyre_object::gc_roots::shadow_stack_get(index_slot)],
        );
    }
    Err(PyError::type_error(format!(
        "'{}' object is not subscriptable",
        w_type_get_name(pyre_object::gc_roots::shadow_stack_get(type_slot)),
    )))
}

/// BINARY_SUBSCR fast path: return the receiver's type, its version tag, and
/// the `__getitem__` [`getitem`] would dispatch, so the full-body walker can
/// inline the subscript in place of the opaque residual.
///
/// Admits the two receiver shapes whose subscript the type's own MRO owns:
/// a builtin sequence layout overriding `__getitem__` (the
/// [`subclass_special_override`] arm) and a user instance (the
/// [`getitem_instance`] arm).  Every other receiver — including a `dict`
/// layout, which reaches its strategy arm without an override consultation —
/// returns `None` and keeps the residual.
///
/// Both arms resolve from `ob_type` and `w_class` alone, so pinning those two
/// plus the returned version tag is what makes the answer constant for the
/// trace; the caller owes those guards.
///
/// # Safety
/// `w_obj` must be a live object.
pub unsafe fn getitem_fast_path(
    w_obj: PyObjectRef,
) -> Option<(PyObjectRef, u64, PyObjectRef, PyObjectRef)> {
    unsafe {
        let (w_type, method) = if is_list(w_obj)
            || is_tuple(w_obj)
            || is_str(w_obj)
            || pyre_object::bytesobject::is_bytes_like(w_obj)
            || pyre_object::is_w_range(w_obj)
        {
            let (method, w_type) = subclass_special_override(w_obj, "__getitem__")?;
            (w_type, method)
        } else if is_instance(w_obj) {
            let w_type = w_instance_get_type(w_obj);
            if w_type.is_null() {
                return None;
            }
            (w_type, lookup_in_type_where(w_type, "__getitem__")?)
        } else {
            return None;
        };
        let version_tag = w_type_version_tag(w_type);
        if version_tag == 0 {
            return None;
        }
        // An in-place `ObjectMutableCell` write does not move `version_tag`, so
        // the tag alone does not make `method` green.  Hand the cell back and
        // let the caller pay [`type_attr_object_cell`]'s getfield and guard.
        let cell = type_attr_object_cell(w_type, Wtf8::new("__getitem__"));
        Some((w_type, version_tag, method, cell))
    }
}

/// GET_ITER fast path: return the receiver's type, its version tag, and the
/// `__iter__` [`iter`] would dispatch for a user instance, so the full-body
/// walker can inline the method in place of the opaque residual.
///
/// This mirrors only [`iter`]'s instance arm.  Iterable layouts claimed by an
/// earlier arm, including the unpack iterator, the type-object metaclass arm
/// and the later generic non-instance lookup retain the residual path.
///
/// The caller owes the `iter_check_is_iterator` step this does not perform:
/// the value the method returns has to carry `__next__` on its type.
///
/// # Safety
/// `w_obj` must be a live object.
pub unsafe fn iter_fast_path(
    w_obj: PyObjectRef,
) -> Option<(PyObjectRef, u64, PyObjectRef, PyObjectRef)> {
    unsafe {
        if crate::module::r#struct::is_unpack_iter(w_obj) || !is_instance(w_obj) {
            return None;
        }
        let w_type = w_instance_get_type(w_obj);
        if w_type.is_null() {
            return None;
        }
        let method = lookup_in_type_where(w_type, "__iter__")?;
        // descroperation.py:339-341 — an explicit `__iter__ = None` marks the
        // type non-iterable even though the lookup succeeds.
        if is_none(method) {
            return None;
        }
        let version_tag = w_type_version_tag(w_type);
        if version_tag == 0 {
            return None;
        }
        // An in-place `ObjectMutableCell` write does not move `version_tag`, so
        // the tag alone does not make `method` green.  Hand the cell back and
        // let the caller pay [`type_attr_object_cell`]'s getfield and guard.
        let cell = type_attr_object_cell(w_type, Wtf8::new("__iter__"));
        Some((w_type, version_tag, method, cell))
    }
}

/// FOR_ITER fast path: return the receiver's type, its version tag, and the
/// `__next__` [`next`] would dispatch for a user instance, so the full-body
/// walker can inline the method in place of the opaque residual.
///
/// This mirrors only [`next`]'s instance arm.  Iterator layouts claimed by an
/// earlier arm, including the unpack iterator, and the later generic
/// non-instance lookup retain the residual path.
///
/// # Safety
/// `w_obj` must be a live object.
pub unsafe fn next_fast_path(
    w_obj: PyObjectRef,
) -> Option<(PyObjectRef, u64, PyObjectRef, PyObjectRef)> {
    unsafe {
        if crate::module::r#struct::is_unpack_iter(w_obj) || !is_instance(w_obj) {
            return None;
        }
        let w_type = w_instance_get_type(w_obj);
        if w_type.is_null() {
            return None;
        }
        let method = lookup_in_type_where(w_type, "__next__")?;
        let version_tag = w_type_version_tag(w_type);
        if version_tag == 0 {
            return None;
        }
        // An in-place `ObjectMutableCell` write does not move `version_tag`, so
        // the tag alone does not make `method` green.  Hand the cell back and
        // let the caller pay [`type_attr_object_cell`]'s getfield and guard.
        let cell = type_attr_object_cell(w_type, Wtf8::new("__next__"));
        Some((w_type, version_tag, method, cell))
    }
}

#[inline(never)]
/// `functional.py W_Range.descr_getitem` — integer index returns
/// the member `start + i*step` (negative folded, bounds-checked); a slice
/// returns a NEW `range` object, not a list.  Indices and members are
/// kept in bignum so a range past a machine word is still subscriptable.
unsafe fn getitem_range(obj: PyObjectRef, index: PyObjectRef) -> PyResult {
    if is_slice(index) {
        return range_compute_slice(obj, index);
    }
    // `_compute_item` — `space.index(w_index)` then bounds-check.
    // `space.index` runs `__index__` and `range_obj_to_bigint` / `fromint`
    // allocate.  The range and the converted index have to come back off
    // the shadow stack (`functional.py _compute_item`); dropping the pin
    // before `w_range_compute_item` leaves `self` as a from-space word.
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(&[obj, index]);
    let w_index = space_index(pyre_object::gc_roots::shadow_stack_get(base + 1))?;
    let _ = pyre_object::gc_roots::pin_root(w_index);
    let w_index_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    let idx =
        pyre_object::range_obj_to_bigint(pyre_object::gc_roots::shadow_stack_get(w_index_slot));
    match pyre_object::w_range_compute_item(pyre_object::gc_roots::shadow_stack_get(base), &idx) {
        Some(v) => Ok(v),
        None => Err(PyError::index_error("range object index out of range")),
    }
}

/// `functional.py compute_slice_indices3` — resolve a slice's
/// (start, stop, step) against a wrapped `length`, in bignum.
unsafe fn compute_slice_indices3_big(
    slice: PyObjectRef,
    length: &BigInt,
) -> Result<(BigInt, BigInt, BigInt), PyError> {
    use num_traits::{One, Zero};
    let _roots = pyre_object::gc_roots::push_roots();
    let slice_slot = pyre_object::gc_roots::pin_roots(&[slice]);
    // `space.index` below can invoke arbitrary Python. RPython's GC transform
    // keeps both the slice object and incoming rbigint live across every
    // callback.  The start/stop/step field pointers are the same class as
    // `range_hash_method`: pin them before `fromint`.
    let length = RBigIntGcRoot::new(length.translated_alias());
    let zero = BigInt::zero();
    let one = BigInt::one();
    let w_step = w_slice_get_step(pyre_object::gc_roots::shadow_stack_get(slice_slot));
    let step_slot = pyre_object::gc_roots::pin_roots(&[w_step]);
    let w_step = pyre_object::gc_roots::shadow_stack_get(step_slot);
    // RPython's stack map roots each of these unboxed rbigint values while
    // the following slice component's `space.index()` can call Python.
    let step = RBigIntGcRoot::new(if is_none(w_step) {
        one.translated_alias()
    } else {
        let s = pyre_object::range_obj_to_bigint(space_index(
            pyre_object::gc_roots::shadow_stack_get(step_slot),
        )?);
        if s.is_zero() {
            return Err(PyError::new(
                PyErrorKind::ValueError,
                "slice step cannot be zero",
            ));
        }
        s
    });
    let negative_step = *step < zero;
    let w_start = w_slice_get_start(pyre_object::gc_roots::shadow_stack_get(slice_slot));
    let start_slot = pyre_object::gc_roots::pin_roots(&[w_start]);
    let w_start = pyre_object::gc_roots::shadow_stack_get(start_slot);
    let start = RBigIntGcRoot::new(if is_none(w_start) {
        if negative_step {
            &*length - &one
        } else {
            zero.translated_alias()
        }
    } else {
        let st = pyre_object::range_obj_to_bigint(space_index(
            pyre_object::gc_roots::shadow_stack_get(start_slot),
        )?);
        if st < zero {
            let st = st + &*length;
            if st < zero {
                if negative_step {
                    one.neg()
                } else {
                    zero.translated_alias()
                }
            } else {
                st
            }
        } else if st >= *length {
            if negative_step {
                &*length - &one
            } else {
                length.translated_alias()
            }
        } else {
            st
        }
    });
    let w_stop = w_slice_get_stop(pyre_object::gc_roots::shadow_stack_get(slice_slot));
    let stop_slot = pyre_object::gc_roots::pin_roots(&[w_stop]);
    let w_stop = pyre_object::gc_roots::shadow_stack_get(stop_slot);
    let stop = RBigIntGcRoot::new(if is_none(w_stop) {
        if negative_step {
            one.neg()
        } else {
            length.translated_alias()
        }
    } else {
        let sp = pyre_object::range_obj_to_bigint(space_index(
            pyre_object::gc_roots::shadow_stack_get(stop_slot),
        )?);
        if sp < zero {
            let sp = sp + &*length;
            if sp < zero {
                if negative_step {
                    one.neg()
                } else {
                    zero.translated_alias()
                }
            } else {
                sp
            }
        } else if sp >= *length {
            if negative_step {
                &*length - &one
            } else {
                length.translated_alias()
            }
        } else {
            sp
        }
    });
    Ok((
        start.translated_alias(),
        stop.translated_alias(),
        step.translated_alias(),
    ))
}

/// `functional.py W_Range._compute_slice` — build the NEW `range`
/// a slice of `obj` denotes.
unsafe fn range_compute_slice(obj: PyObjectRef, slice: PyObjectRef) -> PyResult {
    let _roots = pyre_object::gc_roots::push_roots();
    // `fromint` of `w_length` collects; the slice is a nursery object whose
    // start/stop/step words would otherwise be from-space by the time
    // `compute_slice_indices3` reads them (`functional.py _compute_slice`).
    let base = pyre_object::gc_roots::pin_roots(&[obj, slice]);
    let len_obj = pyre_object::w_range_length(pyre_object::gc_roots::shadow_stack_get(base));
    let len_slot = pyre_object::gc_roots::pin_roots(&[len_obj]);
    let len_b = pyre_object::range_obj_to_bigint(pyre_object::gc_roots::shadow_stack_get(len_slot));
    let (sl_start, sl_stop, sl_step) =
        compute_slice_indices3_big(pyre_object::gc_roots::shadow_stack_get(base + 1), &len_b)?;
    let sl_start = RBigIntGcRoot::new(sl_start);
    let sl_stop = RBigIntGcRoot::new(sl_stop);
    let sl_step = RBigIntGcRoot::new(sl_step);
    let (rstart, _rstop, rstep) =
        pyre_object::w_range_fields(pyre_object::gc_roots::shadow_stack_get(base));
    let field_base = pyre_object::gc_roots::pin_roots(&[rstart, rstep]);
    let rstart_b = RBigIntGcRoot::new(pyre_object::range_obj_to_bigint(
        pyre_object::gc_roots::shadow_stack_get(field_base),
    ));
    let rstep_b = RBigIntGcRoot::new(pyre_object::range_obj_to_bigint(
        pyre_object::gc_roots::shadow_stack_get(field_base + 1),
    ));
    // Each product collects, so it is computed before `rstart_b` is read for
    // the sum.
    let start_offset = &*sl_start * &*rstep_b;
    let substart = RBigIntGcRoot::new(&*rstart_b + &start_offset);
    let substep = RBigIntGcRoot::new(&*rstep_b * &*sl_step);
    // Compute and root every unboxed output before the first wrapping
    // allocation, which may collect.
    let stop_offset = &*sl_stop * &*rstep_b;
    let substop = RBigIntGcRoot::new(&*rstart_b + &stop_offset);
    let _roots = pyre_object::gc_roots::push_roots();
    let w_substart = pyre_object::range_bigint_to_obj(substart.translated_alias());
    let _ = pyre_object::gc_roots::pin_root(w_substart);
    let substart_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    let w_substep = pyre_object::range_bigint_to_obj(substep.translated_alias());
    let _ = pyre_object::gc_roots::pin_root(w_substep);
    let substep_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    // functional.py:523-526 tests `if w_stop`, i.e. whether the wrapped
    // pointer exists, not whether its integer payload is zero.  The wrapped
    // result of compute_slice_indices3 is always present, so compute the stop
    // lane even when its value is 0 (notably for `r[-1:-3:-1]`).
    let w_substop = pyre_object::range_bigint_to_obj(substop.translated_alias());
    let _ = pyre_object::gc_roots::pin_root(w_substop);
    let substop_slot = pyre_object::gc_roots::shadow_stack_len() - 1;
    Ok(pyre_object::w_range_new(
        pyre_object::gc_roots::shadow_stack_get(substart_slot),
        pyre_object::gc_roots::shadow_stack_get(substop_slot),
        pyre_object::gc_roots::shadow_stack_get(substep_slot),
        false,
    ))
}

/// `space.type(w_item) is space.w_int or space.w_bool` used by
/// `W_Range.descr_contains/count/index`.  BigInt-backed exact ints share the
/// canonical `int` class through `is_exact_type`; an int subclass must take
/// the elementwise comparison path so its `__eq__` override is honored.
unsafe fn range_integer_fast_path(item: PyObjectRef) -> bool {
    is_bool(item) || pyre_object::is_exact_type(item, &pyre_object::INT_TYPE)
}

/// `range.count(value)` — `functional.py W_Range.descr_count`.
pub(crate) fn range_count_method(args: &[PyObjectRef]) -> PyResult {
    if args.len() != 2 {
        return Err(PyError::type_error(format!(
            "range.count() takes exactly one argument ({} given)",
            crate::type_methods::args_given(args)
        )));
    }
    let obj = args[0];
    let needle = args[1];
    unsafe {
        if range_integer_fast_path(needle) {
            // `fromint` of a machine-int needle collects.
            let _roots = pyre_object::gc_roots::push_roots();
            let base = pyre_object::gc_roots::pin_roots(&[obj, needle]);
            let item =
                pyre_object::range_obj_to_bigint(pyre_object::gc_roots::shadow_stack_get(base + 1));
            return Ok(w_int_new(pyre_object::w_range_contains_bigint(
                pyre_object::gc_roots::shadow_stack_get(base),
                &item,
            ) as i64));
        }
    }
    // `space.sequence_count(self, w_item)` — elementwise scan of the whole
    // sequence.
    sequence_count(obj, needle)
}

/// `range.index(value)` — `functional.py W_Range.descr_index`.
pub(crate) fn range_index_method(args: &[PyObjectRef]) -> PyResult {
    if args.len() != 2 {
        return Err(PyError::type_error(format!(
            "range.index() takes exactly one argument ({} given)",
            crate::type_methods::args_given(args)
        )));
    }
    let obj = args[0];
    let needle = args[1];
    unsafe {
        // int / bool / long needle → O(1) `(value - start) // step`.
        if range_integer_fast_path(needle) {
            // `fromint` of a machine-int needle and `w_range_contains_bigint`
            // collect; the range, the needle and `item` are reloaded after.
            let _roots = pyre_object::gc_roots::push_roots();
            let base = pyre_object::gc_roots::pin_roots(&[obj, needle]);
            let item = RBigIntGcRoot::new(pyre_object::range_obj_to_bigint(
                pyre_object::gc_roots::shadow_stack_get(base + 1),
            ));
            if pyre_object::w_range_contains_bigint(
                pyre_object::gc_roots::shadow_stack_get(base),
                &item,
            ) {
                return Ok(pyre_object::w_range_index_of(
                    pyre_object::gc_roots::shadow_stack_get(base),
                    &item,
                ));
            }
            return Err(PyError::value_error(crate::display::wtf8_format!(
                crate::display::py_repr_wtf8(pyre_object::gc_roots::shadow_stack_get(base + 1))?,
                " is not in range"
            )));
        }
    }
    // `space.sequence_index` — elementwise scan (raises ValueError on miss).
    sequence_index(obj, needle)
}

/// `descroperation.py sequence_index` — the first index whose element
/// `eq_w`-matches `w_item` (`w is w_item or w == w_item`), iterating
/// `w_container` through the iterator protocol; a miss raises `ValueError`.
pub(crate) fn sequence_index(w_container: PyObjectRef, mut w_item: PyObjectRef) -> PyResult {
    let w_iter = pyre_object::with_roots!(w_item => iter(w_container))?;
    // `next`/`eq_w` re-enter Python (`__next__`/`__eq__`) and may collect while
    // the iterator and needle are still needed on the next turn; a raw local is
    // not scanned by the collector, so both live on the shadow stack.  (RPython
    // stack slots are GC roots; Rust's are not.)
    let _roots = pyre_object::gc_roots::push_roots();
    let pair = pyre_object::gc_roots::pin_roots(&[w_iter, w_item]);
    let iter_slot = pair;
    let item_slot = pair + 1;
    let mut index: i64 = 0;
    loop {
        match next(pyre_object::gc_roots::shadow_stack_get(iter_slot)) {
            Ok(w_next) => {
                let _item_roots = pyre_object::gc_roots::push_roots();
                let w_next = pyre_object::gc_roots::pin_root(w_next);
                if eq_w(w_next, pyre_object::gc_roots::shadow_stack_get(item_slot))? {
                    return Ok(w_int_new(index));
                }
                index += 1;
            }
            Err(e) => {
                let (stop, e) = e.matches_stop_iteration_keep();
                if stop {
                    break;
                }
                return Err(e);
            }
        }
    }
    Err(PyError::value_error(
        "sequence.index(x): x not in sequence".to_string(),
    ))
}

/// `descroperation.py sequence_count` — how many elements `eq_w`-match
/// `w_item` (`w is w_item or w == w_item`), scanning `w_container` through the
/// iterator protocol.
pub(crate) fn sequence_count(w_container: PyObjectRef, mut w_item: PyObjectRef) -> PyResult {
    let w_iter = pyre_object::with_roots!(w_item => iter(w_container))?;
    // `next`/`eq_w` re-enter Python and may collect; a raw local is not a root,
    // so the iterator and needle live on the shadow stack.
    let _roots = pyre_object::gc_roots::push_roots();
    let pair = pyre_object::gc_roots::pin_roots(&[w_iter, w_item]);
    let iter_slot = pair;
    let item_slot = pair + 1;
    let mut count: i64 = 0;
    loop {
        match next(pyre_object::gc_roots::shadow_stack_get(iter_slot)) {
            Ok(w_next) => {
                let _item_roots = pyre_object::gc_roots::push_roots();
                let w_next = pyre_object::gc_roots::pin_root(w_next);
                if eq_w(w_next, pyre_object::gc_roots::shadow_stack_get(item_slot))? {
                    count += 1;
                }
            }
            Err(e) => {
                let (stop, e) = e.matches_stop_iteration_keep();
                if stop {
                    break;
                }
                return Err(e);
            }
        }
    }
    Ok(w_int_new(count))
}

/// `descroperation.py sequence_contains` — whether any element `eq_w`-matches
/// `w_item` (`w is w_item or w == w_item`), scanning `w_container` through the
/// iterator protocol.
pub(crate) fn sequence_contains(
    w_container: PyObjectRef,
    mut w_item: PyObjectRef,
) -> Result<bool, PyError> {
    let w_iter = pyre_object::with_roots!(w_item => iter(w_container))?;
    // `next`/`eq_w` re-enter Python and may collect; a raw local is not a root,
    // so the iterator and needle live on the shadow stack.
    let _roots = pyre_object::gc_roots::push_roots();
    let pair = pyre_object::gc_roots::pin_roots(&[w_iter, w_item]);
    let iter_slot = pair;
    let item_slot = pair + 1;
    loop {
        match next(pyre_object::gc_roots::shadow_stack_get(iter_slot)) {
            Ok(w_next) => {
                let _item_roots = pyre_object::gc_roots::push_roots();
                let w_next = pyre_object::gc_roots::pin_root(w_next);
                if eq_w(w_next, pyre_object::gc_roots::shadow_stack_get(item_slot))? {
                    return Ok(true);
                }
            }
            Err(e) => {
                let (stop, e) = e.matches_stop_iteration_keep();
                if stop {
                    break;
                }
                return Err(e);
            }
        }
    }
    Ok(false)
}

/// `range.__iter__()` — fresh `range_iterator` (word-fit or bignum cursor).
pub(crate) fn range_iter_method(args: &[PyObjectRef]) -> PyResult {
    iter(args[0])
}

/// `range.__reversed__()` — `functional.py W_Range.descr_reversed`.
pub(crate) fn range_reversed_method(args: &[PyObjectRef]) -> PyResult {
    unsafe { Ok(pyre_object::w_range_reversed(args[0])) }
}

/// `range.__reduce__()` — `functional.py W_Range.descr_reduce`:
/// `(type(self), (start, stop, step))`.
pub(crate) fn range_reduce_method(args: &[PyObjectRef]) -> PyResult {
    let _roots = pyre_object::gc_roots::push_roots();
    let range_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(args[0]);
    let (start, stop, step) =
        unsafe { pyre_object::w_range_fields(pyre_object::gc_roots::shadow_stack_get(range_slot)) };
    // `range` is bound in builtins as a constructor function, not as the
    // registry type object, so the reconstructor must be that name-bound
    // callable: `pickle.save_global` matches it to `builtins.range`, and
    // `range(start, stop, step)` rebuilds the instance.
    let fields = pyre_object::gc_roots::pin_roots(&[start, stop, step]);
    let range_ctor = builtin_callable("range");
    let ctor_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(range_ctor);
    let state = w_tuple_new(vec![
        pyre_object::gc_roots::shadow_stack_get(fields),
        pyre_object::gc_roots::shadow_stack_get(fields + 1),
        pyre_object::gc_roots::shadow_stack_get(fields + 2),
    ]);
    let state_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(state);
    Ok(w_tuple_new(vec![
        pyre_object::gc_roots::shadow_stack_get(ctor_slot),
        pyre_object::gc_roots::shadow_stack_get(state_slot),
    ]))
}

/// `range.__hash__()` — `functional.py W_Range.descr_hash`: hashes the
/// `(length, start, step)` tuple, collapsing trailing fields to `None`
/// for empty (`(len, None, None)`) and single-element (`(len, start,
/// None)`) ranges so equal ranges hash equal.
pub(crate) fn range_hash_method(args: &[PyObjectRef]) -> PyResult {
    use num_traits::Zero;
    // `range_obj_to_bigint` / `w_range_length` allocate (`fromint`).
    // `args` is a gateway copy; start/step/len_obj have to be shadow-stack
    // slots so `w_tuple_new` does not store from-space words.
    let _roots = pyre_object::gc_roots::push_roots();
    let base = pyre_object::gc_roots::pin_roots(args);
    let range = || pyre_object::gc_roots::shadow_stack_get(base);
    let (start, _stop, step) = unsafe { pyre_object::w_range_fields(range()) };
    let field_base = pyre_object::gc_roots::pin_roots(&[start, step]);
    let len_obj = unsafe { pyre_object::w_range_length(range()) };
    let len_slot = pyre_object::gc_roots::pin_roots(&[len_obj]);
    let len = unsafe {
        pyre_object::range_obj_to_bigint(pyre_object::gc_roots::shadow_stack_get(len_slot))
    };
    let start = pyre_object::gc_roots::shadow_stack_get(field_base);
    let step = pyre_object::gc_roots::shadow_stack_get(field_base + 1);
    let len_obj = pyre_object::gc_roots::shadow_stack_get(len_slot);
    let items = if len.is_zero() {
        vec![len_obj, w_none(), w_none()]
    } else if len.int_eq(1) {
        vec![len_obj, start, w_none()]
    } else {
        vec![len_obj, start, step]
    };
    Ok(w_int_new(hash_w_strict(w_tuple_new(items))?))
}

/// The builtin function `name` (`iter` / `enumerate`) as the
/// reconstructor for an iterator's `__reduce__`.  Mirrors PyPy's
/// `space.getbuiltin(name)` — the reduce tuple's first element must be
/// the live builtin so `pickle` recreates the iterator via `iter(seq)` /
/// `enumerate(iterable)`.
pub(crate) fn builtin_callable(name: &str) -> PyObjectRef {
    let ctx = crate::call::getexecutioncontext();
    if ctx.is_null() {
        return PY_NULL;
    }
    unsafe { (*ctx).lookup_builtin(name).unwrap_or(PY_NULL) }
}

/// Python 3.14 `_PyEval_GetBuiltin(name)` for operations whose result is
/// observably resolved in the current frame (notably iterator `__reduce__`).
/// The frame's selected builtin mapping may be a dict subclass or
/// `MappingProxyType`; propagate its lookup error and report a missing entry
/// as AttributeError, matching `_PyEval_GetBuiltin`.
fn frame_builtin_callable(name: &str) -> PyResult {
    crate::eval::CURRENT_FRAME.with(|current| {
        let frame = current.get();
        if !frame.is_null() {
            let w_builtin = unsafe { (*frame).get_builtin() };
            if !w_builtin.is_null() && unsafe { pyre_object::is_module(w_builtin) } {
                let w_dict = unsafe { pyre_object::w_module_get_w_dict(w_builtin) };
                if !w_dict.is_null()
                    && let Some(callable) = finditem_str(w_dict, name)?
                {
                    return Ok(callable);
                }
            }
            return Err(PyError::attribute_error(name));
        }
        let callable = builtin_callable(name);
        if callable.is_null() {
            Err(PyError::attribute_error(name))
        } else {
            Ok(callable)
        }
    })
}

/// Build the common iterator pickle tuple after the reconstructor lookup and
/// the subsequent state read.  Keep every component rooted while tuple
/// allocation runs: these methods are deliberately exercised with a hostile
/// builtins dict whose equality hook can exhaust the receiver and allocate.
fn iterator_reduce_tuple(
    callable: PyObjectRef,
    seq: PyObjectRef,
    index: i64,
    empty_kind: u8,
) -> PyResult {
    let _roots = pyre_object::gc_roots::push_roots();
    // A negative cursor is the exhausted sentinel the list iterators store,
    // and `listiter_reduce`/`listreviter_reduce` report the empty producer for
    // it even while the source list is still referenced.
    if seq.is_null() || index < 0 {
        let sp = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(callable);
        // CPython 3.14 retains the concrete producer shape for the
        // specialized string/list iterators; generic sequence, bytes and
        // tuple iterators use the canonical empty tuple.
        let empty = match empty_kind {
            1 => w_str_new_managed(""),
            2 => w_list_new(vec![]),
            _ => w_tuple_new(vec![]),
        };
        let _ = pyre_object::gc_roots::pin_root(empty);
        let state = w_tuple_new(vec![pyre_object::gc_roots::shadow_stack_get(sp + 1)]);
        let _ = pyre_object::gc_roots::pin_root(state);
        return Ok(w_tuple_new(vec![
            pyre_object::gc_roots::shadow_stack_get(sp),
            pyre_object::gc_roots::shadow_stack_get(sp + 2),
        ]));
    }
    let sp = pyre_object::gc_roots::pin_roots(&[callable, seq]);
    let state = w_tuple_new(vec![pyre_object::gc_roots::shadow_stack_get(sp + 1)]);
    let _ = pyre_object::gc_roots::pin_root(state);
    let w_index = w_int_new(index);
    let _ = pyre_object::gc_roots::pin_root(w_index);
    Ok(w_tuple_new(vec![
        pyre_object::gc_roots::shadow_stack_get(sp),
        pyre_object::gc_roots::shadow_stack_get(sp + 2),
        pyre_object::gc_roots::shadow_stack_get(sp + 3),
    ]))
}

/// `sequenceiterator.__reduce__()` — `iterobject.py
/// W_AbstractSeqIterObject.descr_reduce`: `(iter, (seq,), index)` for a live
/// sequence; an exhausted iterator (`w_seq is None`) pickles to `_empty_iterable`
/// (`iterobject.py`) = `(iter, ((),))` so it restores empty.
pub(crate) fn seq_iter_reduce_method(args: &[PyObjectRef]) -> PyResult {
    // CPython 3.14 issue #101765: resolving `builtins.iter` can run an
    // equality hook which exhausts this iterator.  Root the receiver, perform
    // that lookup first, and only then read its live sequence and cursor.
    let _roots = pyre_object::gc_roots::push_roots();
    let sp = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(args[0]);
    let callable = builtin_callable("iter");
    let _ = pyre_object::gc_roots::pin_root(callable);
    unsafe {
        let receiver = pyre_object::gc_roots::shadow_stack_get(sp);
        iterator_reduce_tuple(
            pyre_object::gc_roots::shadow_stack_get(sp + 1),
            pyre_object::w_seq_iter_seq(receiver),
            pyre_object::seq_index_to_i64(pyre_object::w_seq_iter_index(receiver)),
            pyre_object::w_seq_iter_empty_kind(receiver),
        )
    }
}

/// Python 3.14 `calliter_reduce` — a live `iter(callable, sentinel)` reduces
/// to `(iter, (callable, sentinel))`; an exhausted iterator reduces through
/// the same empty-iterator shape as the other builtin iterators.
pub(crate) fn callable_iter_reduce_method(args: &[PyObjectRef]) -> PyResult {
    let obj = args.first().copied().unwrap_or(PY_NULL);
    if obj.is_null() || unsafe { !pyre_object::operation::is_callable_iterator(obj) } {
        return Err(PyError::type_error(
            "descriptor '__reduce__' requires a 'callable_iterator' object",
        ));
    }
    // The registered arity is only a dispatch hint; surplus positional
    // arguments must be rejected here.
    if args.len() > 1 {
        return Err(PyError::type_error(format!(
            "callable_iterator.__reduce__() takes no arguments ({} given)",
            args.len() - 1,
        )));
    }
    let _roots = pyre_object::gc_roots::push_roots();
    let sp = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(obj);
    let _ = pyre_object::gc_roots::pin_root(builtin_callable("iter"));
    let obj = || pyre_object::gc_roots::shadow_stack_get(sp);
    let callable = unsafe { pyre_object::operation::w_callable_iterator_get_callable(obj()) };
    let state = if callable.is_null() {
        let empty = w_tuple_new(vec![]);
        let _ = pyre_object::gc_roots::pin_root(empty);
        w_tuple_new(vec![pyre_object::gc_roots::shadow_stack_get(
            pyre_object::gc_roots::shadow_stack_len() - 1,
        )])
    } else {
        let sentinel = unsafe { pyre_object::operation::w_callable_iterator_get_sentinel(obj()) };
        let pair = pyre_object::gc_roots::pin_roots(&[callable, sentinel]);
        w_tuple_new(vec![
            pyre_object::gc_roots::shadow_stack_get(pair),
            pyre_object::gc_roots::shadow_stack_get(pair + 1),
        ])
    };
    let _ = pyre_object::gc_roots::pin_root(state);
    Ok(w_tuple_new(vec![
        pyre_object::gc_roots::shadow_stack_get(sp + 1),
        pyre_object::gc_roots::shadow_stack_get(pyre_object::gc_roots::shadow_stack_len() - 1),
    ]))
}

/// Narrows a `__setstate__` cursor to the `Signed` iterator index; a value
/// wider than a machine word raises `OverflowError`.
fn cursor_from_i64(index: i64) -> Result<isize, PyError> {
    pyre_object::iterobject::seq_index_from_i64(index)
        .ok_or_else(|| PyError::overflow_error("Python int too large to convert to C ssize_t"))
}

/// The cursor argument shared by every builtin iterator's `__setstate__`.
/// Python 3.14 reads it with `PyLong_AsSsize_t`, so an `int` (or a subclass) is
/// the only accepted state — the `__index__` protocol is not consulted — and a
/// value too wide for a machine word raises `OverflowError`.  PyPy unwraps with
/// `space.int_w` (`iterobject.py:41`), which does run `__index__`; the
/// observable behaviour target is 3.14.
fn iter_setstate_index(state: PyObjectRef) -> Result<i64, PyError> {
    if state.is_null()
        || !unsafe {
            pyre_object::is_int(state) || pyre_object::is_long(state) || pyre_object::is_bool(state)
        }
    {
        return Err(PyError::type_error("an integer is required"));
    }
    if unsafe { pyre_object::is_long(state) } {
        let big = unsafe { pyre_object::longobject::w_long_get_value(state) };
        if pyre_object::longobject::jit_bigint_to_i64_fits(big) == 0 {
            return Err(PyError::overflow_error(
                "Python int too large to convert to C ssize_t",
            ));
        }
    }
    int_w(state)
}

/// The live length a `W_SeqIterObject` cursor is clamped against, for the
/// producers whose `__setstate__` knows one.  The shared `sequenceiterator`
/// identity reaches its elements through `__getitem__` alone, so it has no
/// length to clamp with (`iter_setstate`, iterobject.c) and reports `None`;
/// an out-of-range cursor there is absorbed by `next` raising StopIteration
/// on the IndexError.
unsafe fn seq_iter_clamp_length(seq: PyObjectRef) -> Option<i64> {
    unsafe {
        if is_str(seq) {
            Some(pyre_object::unicodeobject::w_str_len(seq) as i64)
        } else if pyre_object::bytesobject::is_bytes_like(seq) {
            Some(pyre_object::bytesobject::bytes_like_len(seq) as i64)
        } else if pyre_object::interp_array::is_array(seq) {
            Some(pyre_object::interp_array::w_array_len(seq) as i64)
        } else {
            None
        }
    }
}

/// `sequenceiterator.__setstate__(index)` — `iterobject.py descr_setstate
/// W_AbstractSeqIterObject.descr_setstate`: restore the cursor only while the
/// sequence is live, clamping a negative index to 0.
///
/// The producer-specific identities 3.14 splits this payload into each clamp
/// the cursor to the sequence's *current* length, so a state past the end
/// pickles as exhausted rather than verbatim; `bytearray_iterator` instead
/// stores the -1 exhausted sentinel for a negative state, one-way, the way
/// `list_iterator` does.  PyPy stores every state verbatim except in
/// `W_FastUnicodeIterObject.descr_setstate` (`iterobject.py`), which
/// clamps because it must recompute a byte offset from the cursor.
pub(crate) fn seq_iter_setstate_method(args: &[PyObjectRef]) -> PyResult {
    // `args` is the gateway's native copy; `iter_setstate_index` can collect.
    let mut w_iter = args[0];
    let mut index = pyre_object::with_roots!(w_iter => iter_setstate_index(args[1]))?;
    unsafe {
        let seq = pyre_object::w_seq_iter_seq(w_iter);
        if seq.is_null() || pyre_object::w_seq_iter_index(w_iter) < 0 {
            return Ok(w_none());
        }
        if index < 0 {
            index = if pyre_object::iterobject::is_bytearray_iter(w_iter) {
                -1
            } else {
                0
            };
        } else if let Some(length) = seq_iter_clamp_length(seq) {
            index = index.min(length);
        }
        pyre_object::w_seq_iter_set_index(w_iter, cursor_from_i64(index)?);
    }
    Ok(w_none())
}

/// `sequenceiterator.__length_hint__()` — `W_AbstractSeqIterObject.getlength`
/// (iterobject.py): `len(seq) - index` recomputed from the LIVE sequence
/// — `space.len(w_seq)`, so a subclass `__len__` override or a mutation made
/// mid-iteration is reflected — clamped to 0.  An exhausted (cleared) sequence
/// reports 0.
///
/// A sequence whose type has no `__len__` reports `NotImplemented` rather than
/// raising: `iter_len` (`iterobject.c`) guards the length read with
/// `_PyObject_HasLen`, and a `__getitem__`-only sequence is exactly the case
/// that guard exists for.  A `__len__` that raises still propagates.  This
/// intentionally differs from PyPy's `getlength`, which lets `space.len` raise;
/// the observable behaviour target is 3.14.
pub(crate) fn seq_iter_length_hint_method(args: &[PyObjectRef]) -> PyResult {
    unsafe {
        let seq = pyre_object::w_seq_iter_seq(args[0]);
        // A negative cursor is `bytearray_iterator`'s exhausted sentinel; it
        // keeps its source referenced but reports nothing remaining.
        if seq.is_null() || pyre_object::w_seq_iter_index(args[0]) < 0 {
            return Ok(w_int_new(0));
        }
        if is_instance(seq) && lookup(seq, "__len__").is_none() {
            return Ok(pyre_object::special::w_not_implemented());
        }
        // `args` is the gateway's native copy; `len_w` can run `__len__`.
        let mut w_iter = args[0];
        let length = pyre_object::with_roots!(w_iter => len_w(seq))?;
        let remaining =
            length - pyre_object::seq_index_to_i64(pyre_object::w_seq_iter_index(w_iter));
        Ok(w_int_new(remaining.max(0)))
    }
}

/// `iterobject.py W_AbstractSeqIterObject.descr_reduce`, for the specialized
/// `W_FastListIterObject` payload used by Python 3.14's `list_iterator`.
pub(crate) fn list_iter_reduce_method(args: &[PyObjectRef]) -> PyResult {
    let _roots = pyre_object::gc_roots::push_roots();
    let sp = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(args[0]);
    let callable = frame_builtin_callable("iter")?;
    let _ = pyre_object::gc_roots::pin_root(callable);
    unsafe {
        let receiver = pyre_object::gc_roots::shadow_stack_get(sp);
        iterator_reduce_tuple(
            pyre_object::gc_roots::shadow_stack_get(sp + 1),
            pyre_object::w_list_iter_seq(receiver),
            pyre_object::seq_index_to_i64(pyre_object::w_list_iter_index(receiver)),
            2,
        )
    }
}

/// `list_iterator.__setstate__(index)` — Python 3.14's specialized list
/// iterator carries the exhausted state in the cursor itself, so a negative
/// cursor exhausts the iterator instead of rewinding it to the front the way
/// the generic sequence iterator does, and an index past the end is clamped to
/// the length rather than stored verbatim.
pub(crate) fn list_iter_setstate_method(args: &[PyObjectRef]) -> PyResult {
    // `args` is the gateway's native copy; `iter_setstate_index` can collect.
    let mut w_iter = args[0];
    let mut index = pyre_object::with_roots!(w_iter => iter_setstate_index(args[1]))?;
    unsafe {
        let seq = pyre_object::w_list_iter_seq(w_iter);
        if seq.is_null() {
            return Ok(w_none());
        }
        // `listiter_setstate`: a negative cursor becomes the -1 exhausted
        // sentinel rather than being clamped to zero, and an over-long one
        // stops at the current length.  The source list stays referenced, so a
        // later in-range `__setstate__` revives the iterator.  PyPy's
        // `W_AbstractSeqIterObject.descr_setstate` clamps negatives to zero
        // instead, which resumes iteration from the front.
        let length = pyre_object::w_list_len(seq) as i64;
        if index < 0 {
            index = -1;
        } else if index > length {
            index = length;
        }
        pyre_object::w_list_iter_set_index(w_iter, cursor_from_i64(index)?);
    }
    Ok(w_none())
}

pub(crate) fn list_iter_length_hint_method(args: &[PyObjectRef]) -> PyResult {
    unsafe {
        let seq = pyre_object::w_list_iter_seq(args[0]);
        let index = pyre_object::w_list_iter_index(args[0]);
        if seq.is_null() || index < 0 {
            return Ok(w_int_new(0));
        }
        Ok(w_int_new(
            (pyre_object::w_list_len(seq) as i64 - pyre_object::seq_index_to_i64(index)).max(0),
        ))
    }
}

