    /// typeobject.py:308/333 — once `uses_object_getattribute` /
    /// `uses_object_setattr` is set, the `*_if_not_from_object` fast path
    /// returns `None` (the object default) without an MRO walk;
    /// `mutated()` clears both flags (typeobject.py).
    #[test]
    fn if_not_from_object_respects_flag_and_mutated_reset() {
        // `make_builtin_type` reads the base type's layout, so the type system
        // must be bootstrapped first (matches `make_user_instance`); otherwise
        // the test aborts when run in isolation.
        crate::typedef::init_typeobjects();
        let t = crate::typedef::make_builtin_type("IfNotFromObject", |_| {});
        unsafe {
            pyre_object::typeobject::w_type_set_uses_object_getattribute(t, true);
            pyre_object::typeobject::w_type_set_uses_object_setattr(t, true);
            assert!(getattribute_if_not_from_object(t).is_none());
            assert!(setattr_if_not_from_object(t).is_none());
            mutated_absent(t);
            assert!(!pyre_object::typeobject::w_type_get_uses_object_getattribute(t));
            assert!(!pyre_object::typeobject::w_type_get_uses_object_setattr(t));
        }
    }

    #[test]
    fn isinstance_miss_requires_canonical_object_class_descriptor() {
        crate::typedef::init_typeobjects();
        let t = crate::typedef::make_builtin_type("IsinstanceClassLookup", |_| {});
        unsafe {
            pyre_object::typeobject::w_type_set_uses_object_getattribute(t, true);
            assert!(isinstance_miss_class_lookup_is_pure(t));

            // A `property` is the app-visible hazardous case.  Any MRO
            // replacement is enough to prove the identity gate itself: only
            // the canonical object getset may enter the replay-safe arm.
            crate::type_dict_store(t, "__class__", pyre_object::w_int_new(7));
            mutated(t, "__class__");
            pyre_object::typeobject::w_type_set_uses_object_getattribute(t, true);
            assert!(!isinstance_miss_class_lookup_is_pure(t));
        }
    }

    /// typeobject.py:303-326 — builtin types and a plain user class that
    /// inherit object.__getattribute__ answer `None`, so the layout-agnostic
    /// receiver gate does not route them through an app-level call.
    #[test]
    fn getattribute_if_not_from_object_answers_none_for_object_default_types() {
        crate::typedef::init_typeobjects();
        let checked = [
            (
                "list",
                crate::typedef::gettypeobject(&pyre_object::pyobject::LIST_TYPE),
            ),
            (
                "tuple",
                crate::typedef::gettypeobject(&pyre_object::pyobject::TUPLE_TYPE),
            ),
            (
                "str",
                crate::typedef::gettypeobject(&pyre_object::pyobject::STR_TYPE),
            ),
            (
                "int",
                crate::typedef::gettypeobject(&pyre_object::pyobject::INT_TYPE),
            ),
            (
                "Exception",
                crate::typedef::gettypeobject(&pyre_object::interp_exceptions::EXCEPTION_TYPE),
            ),
        ];
        unsafe {
            for (name, w_type) in checked {
                assert!(!w_type.is_null(), "{name} type is registered");
                assert!(
                    getattribute_if_not_from_object(w_type).is_none(),
                    "{name} inherits object.__getattribute__"
                );
            }
            let plain = make_user_instance();
            let plain_type = w_instance_get_type(plain);
            assert!(getattribute_if_not_from_object(plain_type).is_none());
        }
    }

